window.QSBI_LESSONS=window.QSBI_LESSONS||{};QSBI_LESSONS[8]=[{"id":"08_19","g":8,"l":19,"topic":"Личный финансовый план. Сбережения","module":"Бюджетирование (личные финансы)","format":"Комбинированный","skills":["Финансовое мышление","Принятие решений","Критическое мышление"],"goal":"К концу урока ученик сможет составить личный план сбережений на конкретную цель: рассчитать сумму, срок и ежемесячный взнос, а также указать источник дохода (активный или пассивный).","criteria":["Я формулирую финансовую цель с суммой и сроком.","Я правильно рассчитываю ежемесячный взнос: (цель − уже есть) ÷ число месяцев.","Я различаю активный и пассивный доход и объясняю, откуда возьму деньги на взнос."],"result":"Личный финансовый план сбережений: цель, стоимость в условных тенге, срок, стартовая сумма, ежемесячный взнос, источники дохода и способ хранения.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Сбережения (savings)","real":"Часть дохода, которую откладывают, а не тратят сразу","shown":"Часть дохода, которую откладывают, а не тратят сразу","truth":true,"first":"С"},{"term":"Финансовый план (plan)","real":"Расчёт, сколько, когда и откуда откладывать, чтобы достичь цели","shown":"Доля в компании; её владелец может получать часть прибыли (дивиденды) и выигрывать или терять при изменении цены","truth":false,"first":"Ф"},{"term":"Активный доход","real":"Деньги, которые получаешь, пока сам работаешь: подработка, зарплата","shown":"Деньги, которые получаешь, пока сам работаешь: подработка, зарплата","truth":true,"first":"А"},{"term":"Пассивный доход","real":"Деньги, которые приходят почти без ежедневной работы: проценты по вкладу, дивиденды, аренда","shown":"Расчёт, сколько, когда и откуда откладывать, чтобы достичь цели","truth":false,"first":"П"},{"term":"Инвестиции","real":"Вложение денег (money) с целью получить больше в будущем, но с риском","shown":"Вложение денег (money) с целью получить больше в будущем, но с риском","truth":true,"first":"И"},{"term":"Акция","real":"Доля в компании; её владелец может получать часть прибыли (дивиденды) и выигрывать или терять при изменении цены","shown":"Деньги, которые приходят почти без ежедневной работы: проценты по вкладу, дивиденды, аренда","truth":false,"first":"А"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Сбережения (savings)","def":"Часть дохода, которую откладывают, а не тратят сразу"},{"term":"Финансовый план (plan)","def":"Расчёт, сколько, когда и откуда откладывать, чтобы достичь цели"},{"term":"Активный доход","def":"Деньги, которые получаешь, пока сам работаешь: подработка, зарплата"},{"term":"Пассивный доход","def":"Деньги, которые приходят почти без ежедневной работы: проценты по вкладу, дивиденды, аренда"},{"term":"Инвестиции","def":"Вложение денег (money) с целью получить больше в будущем, но с риском"},{"term":"Акция","def":"Доля в компании; её владелец может получать часть прибыли (дивиденды) и выигрывать или терять при изменении цены"},{"term":"Ежемесячный взнос","def":"Сумма, которую откладываешь каждый месяц"}],"english":"savings — сбережения; finance — финансы; money — деньги; plan — план","concepts":{"head":"Понятия","items":["Финансы (finance) — это управление деньгами (money).","Сбережения (savings) — отложенная часть дохода.","Финансовый план (plan) отвечает на вопросы: на что, сколько, к какому сроку, по сколько в месяц, откуда.","Доход бывает активным (работаешь — получаешь) и пассивным (деньги работают на тебя: проценты, дивиденды по акциям).","Инвестиции могут дать пассивный доход, но несут риск."]},"steps":{"head":"Как составить план, по шагам","items":["Цель по SMART: «Купить велосипед за 90 000 условных тенге к 1 июня»","Посчитать, сколько месяцев до срока","Вычесть то, что уже есть","Разделить остаток на число месяцев — это взнос","Проверить, реален ли взнос при твоих доходах","Если нет — увеличить срок, уменьшить цель или найти доп. доход; ж) выбрать, где хранить: копилка, накопительный счёт"]},"scheme":"Лестница плана «Цель → Сумма → Срок → Уже есть → Взнос в месяц → Источник → Где храню», рядом формула «Взнос = (Цель − Есть) ÷ Месяцы» и две колонки «Активный доход | Пассивный доход».","examples":[{"lab":"Казахстанский","text":"Данияр из Астаны хочет ноутбук за 180 000 условных тенге через 12 месяцев, у него уже есть 36 000. Взнос: (180 000 − 36 000) ÷ 12 = 12 000 в месяц. Его активный доход — подработка репетитором 15 000 в месяц, значит план реален."},{"lab":"Мировой","text":"Уоррен Баффет начал откладывать и инвестировать ещё подростком и называл раннее начало главным преимуществом."}],"mistake":{"myth":"Ученики забывают вычесть уже накопленное или считают срок неверно","fix":"Решите пример у доски дважды — с вычетом и без — и сравните."},"check":[{"q":"Блогинг — активный или пассивный доход?","a":"В основном активный: нужно постоянно создавать контент"},{"q":"Почему сначала сбережения, а потом инвестиции?","a":"Нужна подушка на непредвиденные расходы; инвестиции рискованны"},{"q":"Что делать, если взнос слишком большой?","a":"Увеличить срок или найти доп. доход"}],"kz":{"text":"Otbasy Bank (бывший Жилстройсбербанк Казахстана). Банк работает по системе жилищных строительных сбережений: люди годами регулярно откладывают деньги на жильё, а государство поддерживает накопления премией.","link":"это национальный пример долгосрочного плана сбережений с целью, сроком и ежемесячным взносом."},"world":{"text":"ЦУР ООН № 1 «Ликвидация нищеты» и № 8 «Достойная работа» связаны с финансовой устойчивостью людей: привычка откладывать помогает семьям легче пережить трудные периоды. Во многих странах финансовую грамотность изучают в школе.","link":""},"fact":"Уоррен Баффет купил свои первые акции в 11 лет, в 1941 году, — три акции компании Cities Service. Позже он говорил, что жалеет, что не начал ещё раньше.","cards":[{"n":"1","title":"Активный или пассивный?","lines":["Ситуации: 1) Подработка курьером. 2) Проценты по вкладу. 3) Дивиденды по акциям. 4) Ведение блога. 5) Сдача квартиры в аренду. 6) Репетиторство.","Задание: распределите по колонкам."],"hand":"Сдать: таблицу (активный: 1, 4, 6; пассивный: 2, 3, 5).","answers":[]},{"n":"2","title":"Мой план сбережений","lines":["Задание: заполните: Цель — Стоимость (условные тенге) — Срок (дата) — Месяцев до срока — Уже есть — Взнос в месяц — Источник (активный/пассивный) — Где храню. Проверьте: взнос не больше 30% от вашего условного месячного дохода (возьмите условный доход 20 000)."],"hand":"Сдать: заполненный план.","answers":[]},{"n":"3","title":"Олимпиадные задачи ФГиБ","lines":["Задача 1. Асель хочет купить курс программирования за 120 000 условных тенге через 10 месяцев. У неё уже есть 20 000. Сколько ей нужно откладывать в месяц?","Ответ: (120 000 − 20 000) ÷ 10 = 10 000.","Задача 2. Тимур получает 25 000 условных тенге в месяц и откладывает 20%. Сколько месяцев ему копить на наушники за 40 000?"],"hand":"Сдать: решения.","answers":[["","20% от 25 000 = 5 000; 40 000 ÷ 5 000 = 8 месяцев."]]}],"practice":[{"type":"case","title":"Правило 50/30/20","minutes":10,"source":"Элизабет Уоррен и Амелия Уоррен Тьяги, книга «All Your Worth», США, 2005","hook":"Как профессор Гарварда предложила делить любой доход всего на три части?","story":["Элизабет Уоррен — профессор права в Гарварде, позже сенатор США — много лет изучала, почему семьи попадают в долги.","Вместе с дочерью Амелией она написала книгу о личных финансах и предложила простое правило: делить доход на три части.","Правило стало одним из самых известных в мире способов вести бюджет."],"question":"Айгерим 17 лет. За лето она заработала 100 000 условных тенге. Как, по-вашему, разделить деньги по этому правилу?","options":["50 000 — на нужное, 30 000 — на желания, 20 000 — отложить","Всё отложить, ничего не тратить","Всё потратить сразу, пока есть","80 000 — на желания, 20 000 — на нужное"],"answerIndex":0,"reveal":"Правило 50/30/20: половина дохода — на необходимое, 30% — на желания, 20% — на сбережения и цели. Важно, что желания разрешены: бюджет, в котором нельзя ничего приятного, быстро бросают.","teams":"Команды: распределите 100 000 условных тенге Айгерим по правилу 50/30/20 и назовите по 2 конкретные траты в каждой части.","takeaway":"Откладывать стоит сразу, а не «что останется»: 20% в начале месяца, а не в конце."},{"type":"case","title":"Зефирный тест","minutes":8,"source":"Уолтер Мишел, Стэнфордский университет, конец 1960-х — 1970-е","hook":"Одна зефирка сейчас или две — через 15 минут?","story":["Психолог Уолтер Мишел предлагал детям выбор: съесть одно лакомство сразу или подождать около 15 минут наедине с ним и получить два.","Часть детей ждала: отворачивалась, пела, закрывала глаза. Часть съедала сразу.","Позже учёные сравнивали, как сложилась жизнь детей, которые ждали, и это стало знаменитой историей про силу воли."],"question":"Как вы думаете, что сильнее всего помогало детям дождаться второй зефирки?","options":["Ничего не помогало — все съели сразу","Хитрости: отвлечься, не смотреть на зефирку","Взрослые подсказывали ответ","Просто сильный характер с рождения"],"answerIndex":1,"reveal":"Детям, которые ждали, помогали приёмы: отвернуться, отвлечься, думать о другом. Более поздние исследования (2018) показали, что связь с будущим успехом слабее, чем считали, и сильно зависит от условий в семье. Но главный вывод для денег остаётся: ждать легче, если есть приём, а не только сила воли.","teams":"Команды: придумайте 3 «хитрости», которые помогут подростку не потратить отложенные деньги на импульсивную покупку.","takeaway":"Сбережения — это не про характер, а про систему: автоматически откладывать и не держать деньги «под рукой»."}],"homework":"Вести учёт отложенных денег 2 недели и проверить, соответствует ли он плану; записать, что помогло и что помешало.","support":"Шаблон плана с подсказками в каждой строке и примером Данияра; калькулятор.","advanced":"Посчитать, насколько сократится срок, если 10% суммы положить на накопительный счёт под 12% годовых, и объяснить, почему инвестировать деньги «подушки» рискованно.","photo":{"src":"lessons/img/08_19.jpg","author":"Andre Taissin","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему привычка сберегать важна не только для одного человека, но и для экономики страны?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g08-l19.pptx","name":"19. Личный финансовый план. Сбережения (8 кл).pptx","mb":1.4}},{"id":"08_20","g":8,"l":20,"topic":"Инвестиции и депозит","module":"Бюджетирование (личные финансы)","format":"Комбинированный","skills":["Финансовое мышление","Принятие решений","Критическое мышление"],"goal":"К концу урока ученик сможет сравнить депозит и инвестиции по риску, доходности и доступности денег, рассчитать доход по депозиту за год и объяснить, почему сначала создают подушку безопасности.","criteria":["Я сравниваю депозит и инвестиции по риску, доходности и доступности денег.","Я рассчитываю доход по депозиту и переплату по кредиту за год.","Я объясняю, почему подушка безопасности создаётся раньше инвестиций."],"result":"Таблица сравнения «Депозит — Инвестиции — Кредит» и финансовое решение по кейсу: копить, брать кредит или инвестировать, с расчётом.","stages":[{"stage":"Разминка «Угадай слово»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Сбережения","real":"Часть дохода, отложенная на будущее","shown":"Часть дохода, отложенная на будущее","truth":true,"first":"С"},{"term":"Депозит (deposit)","real":"Вклад: деньги (money), которые положили в банк под проценты на определённых условиях","shown":"Запас денег на 3–6 месяцев обязательных расходов на случай непредвиденных ситуаций","truth":false,"first":"Д"},{"term":"Инвестиции (investment)","real":"Вложение денег в акции, облигации, бизнес с целью заработать больше, но с риском потерь","shown":"Вложение денег в акции, облигации, бизнес с целью заработать больше, но с риском потерь","truth":true,"first":"И"},{"term":"Кредит","real":"Деньги банка в долг, которые возвращают с процентами","shown":"Вклад: деньги (money), которые положили в банк под проценты на определённых условиях","truth":false,"first":"К"},{"term":"Доходность","real":"Сколько процентов в год приносит вложение","shown":"Сколько процентов в год приносит вложение","truth":true,"first":"Д"},{"term":"Подушка безопасности","real":"Запас денег на 3–6 месяцев обязательных расходов на случай непредвиденных ситуаций","shown":"Деньги банка в долг, которые возвращают с процентами","truth":false,"first":"П"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Сбережения","def":"Часть дохода, отложенная на будущее"},{"term":"Депозит (deposit)","def":"Вклад: деньги (money), которые положили в банк под проценты на определённых условиях"},{"term":"Инвестиции (investment)","def":"Вложение денег в акции, облигации, бизнес с целью заработать больше, но с риском потерь"},{"term":"Кредит","def":"Деньги банка в долг, которые возвращают с процентами"},{"term":"Доходность","def":"Сколько процентов в год приносит вложение"},{"term":"Подушка безопасности","def":"Запас денег на 3–6 месяцев обязательных расходов на случай непредвиденных ситуаций"},{"term":"Гарантирование депозитов","def":"Государственная система, которая возвращает вкладчику деньги в пределах установленной суммы, если банк закроется"}],"english":"deposit — вклад; investment — инвестиции; money — деньги","concepts":{"head":"Понятия","items":["Депозит (deposit) — вклад в банке под проценты: риск низкий, доходность умеренная.","Инвестиции (investment) — вложения в акции, облигации, бизнес: доходность может быть выше, но можно и потерять деньги (money).","Кредит — обратная ситуация: ты платишь банку проценты."]},"steps":{"head":"Как принимать решение, по шагам","items":["Есть ли подушка безопасности? Если нет — сначала копим её на депозите или накопительном счёте","Есть ли цель с коротким сроком (до года)? — депозит","Есть ли свободные деньги на годы вперёд? — можно изучать инвестиции","Кредит — только если покупка действительно нужна и платёж посилен"]},"scheme":"«финансовая пирамида приоритетов» снизу вверх: 1) подушка безопасности; 2) сбережения на цели (депозит); 3) инвестиции. Рядом весы «Риск ↔ Доходность».","examples":[{"lab":"Казахстанский","text":"Арман из Караганды хочет велосипед за 15 000 условных тенге, у него есть 3 000 и он откладывает 1 000 в месяц. Вариант А — копить: (15 000 − 3 000) ÷ 1 000 = 12 месяцев, переплаты нет. Вариант Б — кредит 15 000 на год под 15% годовых: переплата 15 000 × 0,15 = 2 250, итого вернуть 17 250. Депозит: 100 000 под 12% годовых через год дадут 12 000 дохода. В Казахстане вклады защищены системой гарантирования депозитов."},{"lab":"Мировой","text":"Стоимость акций может сильно падать — например, во время мирового кризиса 2008 года многие акции подешевели в разы."}],"mistake":{"myth":"«высокая доходность — значит лучше»","fix":"Покажите, что обещание очень высокой гарантированной доходности — признак мошенничества."},"check":[{"q":"Почему нельзя вкладывать подушку в акции?","a":"Может понадобиться срочно, а акции могут подешеветь"},{"q":"Что выгоднее для Армана?","a":"Копить, если он может подождать"},{"q":"Где риск выше — депозит или акции?","a":"Акции"}],"kz":{"text":"Программа «Народное IPO». В 2012 году казахстанцы смогли купить акции национальной компании «КазТрансОйл», а в 2014 году — KEGOC, через Казахстанскую фондовую биржу (KASE).","link":"это пример доступных инвестиций для граждан, у которых есть и доходность, и риск изменения цены."},"world":{"text":"Мировой финансовый кризис 2008 года показал, как опасно брать кредиты сверх возможностей и вкладывать деньги без понимания риска: многие семьи в разных странах потеряли сбережения и жильё.","link":""},"fact":"Одна из первых в мире фондовых бирж появилась в Амстердаме в начале XVII века, когда Голландская Ост-Индская компания (основана в 1602 году) начала продавать свои акции всем желающим.","cards":[{"n":"1","title":"Депозит, инвестиции или кредит?","lines":["Задание: заполните таблицу по строкам «Чьи деньги? — Риск — Доходность — Когда можно забрать деньги» для депозита, инвестиций в акции и кредита."],"hand":"Сдать: таблицу.","answers":[]},{"n":"2","title":"Кейс «Мечта Армана»","lines":["Данные: велосипед стоит 15 000 условных тенге; у Армана есть 3 000; он откладывает 1 000 в месяц. Вариант А: копить. Вариант Б: кредит 15 000 на год под 15% годовых. Вариант В: друг предлагает «вложить 3 000 в проект, который за месяц принесёт 300%».","Задание: посчитайте срок по варианту А и переплату по варианту Б, оцените риск варианта В и выберите решение."],"hand":"Сдать: решение с расчётом","answers":[["","А — 12 месяцев; Б — переплата 2 250, вернуть 17 250; В — признак мошенничества"]]},{"n":"3","title":"Олимпиадные задачи ФГиБ","lines":["Задача 1. Вклад 200 000 условных тенге под 10% годовых без пополнения и без капитализации. Сколько будет на счёте через 2 года?","Задача 2. Ежемесячные обязательные расходы семьи условно 150 000. Финансисты советуют подушку на 3–6 месяцев. Какой минимальный и максимальный размер подушки?"],"hand":"Сдать: решения.","answers":[["","200 000 + 200 000 × 0,10 × 2 = 240 000."],["","450 000 и 900 000 условных тенге."]]}],"practice":[{"type":"case","title":"Пари Уоррена Баффета на миллион","minutes":10,"source":"Уоррен Баффет и Protégé Partners, пари 2008–2017","hook":"Самый известный инвестор мира поспорил на миллион долларов, что простой фонд обгонит профессионалов. Кто выиграл?","story":["В 2007 году Уоррен Баффет предложил пари: за 10 лет простой индексный фонд, который просто покупает 500 крупнейших компаний США, заработает больше, чем фонды, где деньгами управляют профессионалы.","Вызов принял Тед Сайдс из компании Protégé Partners: он выбрал пять «фондов фондов» с профессиональными управляющими.","Ставка — миллион долларов, выигрыш шёл на благотворительность. Пари длилось с 2008 по 2017 год."],"question":"Кто, по-вашему, выиграл пари за 10 лет?","options":["Ничья","Простой индексный фонд Баффета","Оба проиграли деньги","Профессиональные управляющие"],"answerIndex":1,"reveal":"Выиграл Баффет: индексный фонд обогнал выбранные фонды с большим отрывом. Главная причина — у профессиональных фондов высокие комиссии, и они «съедают» доход год за годом. Миллион ушёл благотворительной организации для девочек Girls Inc. в Омахе.","teams":"Команды: перечислите, чем отличаются депозит и инвестиции в фонд — по риску, доходности и тому, как быстро можно забрать деньги.","takeaway":"Инвестиции — на долгий срок и с пониманием комиссий; деньги, которые могут понадобиться скоро, — на депозит."},{"type":"case","title":"Тюльпаномания","minutes":8,"source":"Нидерланды, 1630-е годы; пик и обвал — февраль 1637","hook":"Как цветочная луковица стала стоить как дом, а потом почти ничего?","story":["В Голландии XVII века тюльпаны были модной редкостью. Особенно ценились луковицы с пёстрыми «огненными» лепестками.","Люди покупали луковицы не чтобы сажать, а чтобы перепродать дороже. Цены быстро росли.","В феврале 1637 года покупатели вдруг перестали платить высокие цены — и рынок рухнул. Историки спорят, насколько массовыми были потери, но эта история стала символом «пузыря»."],"question":"Что, по-вашему, было главной ошибкой покупателей луковиц?","options":["Покупали слишком мало","Хранили деньги в банке","Покупали только потому, что цена растёт, а не из-за ценности","Сажали тюльпаны"],"answerIndex":2,"reveal":"Покупатели рассчитывали, что кто-то купит дороже, — так возникает пузырь. Когда новых покупателей не стало, цена упала. С тех пор «тюльпаномания» — пример того, почему нельзя вкладывать всё в одну модную вещь.","teams":"Команды: найдите в современном мире пример «модной» вещи, цена которой может так же взлететь и упасть, и объясните риск.","takeaway":"Если цена растёт только потому, что все покупают, — это риск, а не инвестиция."}],"homework":"Используя депозитный калькулятор на официальном сайте любого казахстанского банка, посчитать доход по вкладу 50 000 условных тенге на 12 месяцев и сравнить с собственным расчётом.","support":"Шаблон таблицы сравнения с готовыми строками и формулы: «доход = сумма × ставка», «переплата = сумма кредита × ставка».","advanced":"Посчитать доход по депозиту 100 000 под 12% годовых за 2 года с капитализацией и без и объяснить разницу.","photo":{"src":"lessons/img/08_20.jpg","author":"Anne Nygård","q":["Что вы видите на фото? Как это связано с нашей темой?","Какое правило из сегодняшнего урока помогло бы людям избежать потерь?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g08-l20.pptx","name":"20. Инвестиции и депозит (8 кл).pptx","mb":1.4}},{"id":"08_21","g":8,"l":21,"topic":"Личный финансовый план. Страхование","module":"Бюджетирование (личные финансы)","format":"Комбинированный","skills":["Финансовое мышление","Принятие решений","Критическое мышление"],"goal":"К концу урока ученик сможет объяснить на 2 примерах, от каких денежных потерь защищает страховка, и рассчитать, когда полис выгоден с учётом страхового взноса и франшизы.","criteria":["Я объясняю, как работает страхование: много людей платят взносы, а выплату получает тот, с кем случился страховой случай.","Я привожу 2 примера, от каких потерь защищает полис.","Я рассчитываю выплату с учётом франшизы и делаю вывод о выгоде."],"result":"Мини-карточка «Нужна ли страховка?» для 2 жизненных ситуаций: риск, вид страхования, взнос, возможная выплата и решение с расчётом.","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Страхование (insurance)","real":"Способ защитить себя от крупной денежной потери: платишь небольшой взнос, а при страховом случае компания компенсирует ущерб","shown":"Способ защитить себя от крупной денежной потери: платишь небольшой взнос, а при страховом случае компания компенсирует ущерб","truth":true,"first":"С"},{"term":"Страховой полис","real":"Договор (документ), где записаны условия: что застраховано, на какую сумму, на какой срок","shown":"Часть ущерба, которую клиент оплачивает сам; компания платит остальное","truth":false,"first":"С"},{"term":"Страховой взнос (премия)","real":"Сумма, которую платят страховой компании за защиту","shown":"Сумма, которую платят страховой компании за защиту","truth":true,"first":"С"},{"term":"Страховой случай","real":"Событие из договора, при котором положена выплата: ДТП, пожар, кража","shown":"Договор (документ), где записаны условия: что застраховано, на какую сумму, на какой срок","truth":false,"first":"С"},{"term":"Страховая выплата","real":"Деньги, которые компания перечисляет при страховом случае","shown":"Деньги, которые компания перечисляет при страховом случае","truth":true,"first":"С"},{"term":"Франшиза","real":"Часть ущерба, которую клиент оплачивает сам; компания платит остальное","shown":"Событие из договора, при котором положена выплата: ДТП, пожар, кража","truth":false,"first":"Ф"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Страхование (insurance)","def":"Способ защитить себя от крупной денежной потери: платишь небольшой взнос, а при страховом случае компания компенсирует ущерб"},{"term":"Страховой полис","def":"Договор (документ), где записаны условия: что застраховано, на какую сумму, на какой срок"},{"term":"Страховой взнос (премия)","def":"Сумма, которую платят страховой компании за защиту"},{"term":"Страховой случай","def":"Событие из договора, при котором положена выплата: ДТП, пожар, кража"},{"term":"Страховая выплата","def":"Деньги, которые компания перечисляет при страховом случае"},{"term":"Франшиза","def":"Часть ущерба, которую клиент оплачивает сам; компания платит остальное"},{"term":"Обязательное страхование","def":"Виды страхования, которые требует закон, например страхование ответственности владельцев автомобилей"}],"english":"insurance — страхование; finance — финансы; emotions — эмоции; plan — план","concepts":{"head":"Понятия","items":["Страхование (insurance) — часть личных финансов (finance) и финансового плана (plan): оно не приносит доход, а защищает от больших потерь.","Важно отделять эмоции (emotions) от расчёта: страх или азарт не должны принимать решение вместо цифр."]},"steps":{"head":"Как работает, по шагам","items":["Много клиентов платят небольшие взносы в общий фонд страховой компании","У немногих случается страховой случай","Они подают заявление и документы","Компания проверяет случай по условиям полиса","Выплачивает ущерб минус франшиза"]},"scheme":"Много человечков → стрелки «взносы» → «фонд страховой компании» → одна стрелка «выплата» к человечку с молнией (страховой случай). Внизу формула «Выплата = Ущерб − Франшиза (не больше страховой суммы)».","examples":[{"lab":"Казахстанский","text":"В Казахстане владельцы автомобилей по закону обязаны оформлять страхование гражданско-правовой ответственности: если водитель повредит чужую машину, ущерб пострадавшему оплатит страховая компания."},{"lab":"Пример с цифрами","text":"Семья застраховала квартиру в Шымкенте от затопления, взнос 15 000 условных тенге в год; соседи сверху залили ремонт на 400 000, франшиза 20 000 — выплата 380 000."},{"lab":"Мировой","text":"После Великого лондонского пожара 1666 года в Англии появились первые компании страхования от пожаров."}],"mistake":{"myth":"Ученики думают, что страховка покрывает всё","fix":"Прочитайте условия учебного полиса и найдите исключения (например, умышленная порча не покрывается)."},"check":[{"q":"Если страховой случай не произошёл, взнос «пропал»?","a":"Нет, он оплатил защиту на этот период, как плата за спокойствие"},{"q":"Что такое франшиза 10 000 при ущербе 8 000?","a":"Выплаты не будет, ущерб меньше франшизы"},{"q":"Почему страховать дешёвые вещи часто невыгодно?","a":"Взнос может быть сопоставим со стоимостью вещи"}],"kz":{"text":"Обязательное страхование автогражданской ответственности в Казахстане. Закон обязывает владельцев транспортных средств страховать свою ответственность перед другими участниками движения: при ДТП пострадавший получает выплату от страховой компании виновника.","link":"это пример того, как страхование защищает не только тебя, но и других."},"world":{"text":"Изменение климата увеличивает число наводнений, ураганов и пожаров в мире, и страховые компании пересматривают цены и условия; это связано с ЦУР № 13 «Борьба с изменением климата».","link":""},"fact":"Знаменитый страховой рынок Lloyd's of London вырос из кофейни Эдварда Ллойда, открытой в Лондоне в 1680-х годах: там собирались моряки, купцы и страховщики, чтобы договариваться о страховании кораблей и грузов.","cards":[{"n":"1","title":"Страховой случай или нет?","lines":["Условия учебного полиса на смартфон: покрывает разбитый экран и кражу; не покрывает потерю по невнимательности и умышленную порчу; франшиза 5 000 условных тенге.","Ситуации: 1) Телефон украли из сумки. 2) Оставил телефон в такси. 3) Уронил, разбил экран — ремонт 30 000. 4) Разбил в гневе."],"hand":"Сдать: ответы (1 — да; 2 — нет; 3 — да, выплата 25 000; 4 — нет).","answers":[]},{"n":"2","title":"Нужна ли страховка?","lines":["Ситуация А: велосипед стоит 120 000 условных тенге, полис от кражи — 6 000 в год, франшиза 10 000. Ситуация Б: зарядка за 3 000, страховка — 1 500 в год.","Задание: для каждой укажите риск, взнос, выплату при страховом случае и решите, нужна ли страховка."],"hand":"Сдать: таблицу с выводом (подсказка: А — выплата 110 000, выгодно; Б — взнос составляет половину стоимости, невыгодно).","answers":[]},{"n":"3","title":"Олимпиадные задачи ФГиБ","lines":["Задача 1. Застрахован ноутбук на 250 000 условных тенге, франшиза 15 000. Ремонт после залития стоит 90 000. Какой будет выплата?","Задача 2. 200 клиентов платят по 4 000 условных тенге в год. Ожидается 5 страховых случаев по 120 000. Хватит ли фонда на выплаты и сколько останется на расходы компании?"],"hand":"Сдать: решения.","answers":[["","90 000 − 15 000 = 75 000."],["","Фонд 800 000, выплаты 600 000, останется 200 000."]]}],"practice":[{"type":"case","title":"Кофейня Ллойда","minutes":9,"source":"Кофейня Эдварда Ллойда, Лондон, конец 1680-х; позже — страховой рынок Lloyd's of London","hook":"Как кофейня в Лондоне стала самым известным страховым рынком мира?","story":["В конце XVII века в лондонскую кофейню Эдварда Ллойда приходили моряки, купцы и судовладельцы — там узнавали новости о кораблях.","Корабль мог утонуть в шторме, и купец терял всё. Поэтому богатые люди в кофейне стали брать на себя часть риска: получали плату, а если корабль погибал, возмещали убыток.","Из этих встреч вырос рынок Lloyd's of London, который работает до сих пор."],"question":"Купец везёт груз через море. Что поможет ему не разориться, если корабль утонет?","options":["Ничего — надеяться на удачу","Не платить морякам","Заплатить небольшой взнос тем, кто возьмёт риск на себя","Отправить весь товар одним кораблём"],"answerIndex":2,"reveal":"Так и родилось страхование: много людей платят небольшие взносы, а пострадавший получает большую выплату. Риск делится на всех — один не разоряется.","teams":"Команды: придумайте страховку для школьной ярмарки. От чего страхуем, сколько платим взнос, кто и когда получает выплату?","takeaway":"Страхование — это способ поделить большой риск на маленькие понятные платежи."},{"type":"case","title":"Страховка на смартфон","minutes":8,"source":"Условная ситуация на типичных условиях страхования гаджетов","hook":"Стоит ли страховать новый телефон?","story":["Телефон стоит 300 000 условных тенге. Магазин предлагает страховку на год за 30 000.","В договоре — франшиза 20 000: эту часть убытка всегда платит сам владелец.","Страховка не покрывает потерю телефона, только поломку и кражу с заявлением в полицию."],"question":"Телефон разбился через полгода. Ремонт стоит 80 000. Сколько заплатит страховая?","options":["60 000 (80 000 минус франшиза 20 000)","300 000 — цену нового телефона","Ничего не заплатит","80 000 — весь ремонт"],"answerIndex":0,"reveal":"Страховая заплатит 60 000, а 20 000 франшизы — владелец. Вместе с ценой страховки (30 000) он потратил 50 000 вместо 80 000. А если бы телефон потерялся, страховка не помогла бы вовсе — поэтому договор надо читать.","teams":"Команды: посчитайте, в каких случаях страховка выгодна, а в каких — нет. Найдите в условиях одну «ловушку».","takeaway":"Перед покупкой страховки смотрите три вещи: цену, франшизу и исключения."}],"homework":"Спросить у взрослых, какие виды страхования есть в семье (без сумм), и записать, от какого риска защищает каждый; если нет — придумать, какой полис был бы полезен и почему.","support":"Схема страхования с подписями, формула выплаты, список видов страхования с примерами рисков.","advanced":"Рассчитать, при какой вероятности страхового случая страхование телефона выгодно клиенту, если взнос 9 000 в год, а ремонт стоит 60 000.","photo":{"src":"lessons/img/08_21.jpg","author":"Erik Witsoe","q":["Что вы видите на фото? Как это связано с нашей темой?","Как рост природных рисков влияет на стоимость страховки и что может сделать человек, чтобы снизить свой риск?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g08-l21.pptx","name":"21. Личный финансовый план. Страхование (8 кл).pptx","mb":1.5}},{"id":"08_22","g":8,"l":22,"topic":"Семейный бюджет и инвестирование","module":"Бюджетирование (личные финансы)","format":"Комбинированный","skills":["Финансовое мышление","Критическое мышление"],"goal":"К концу урока ученик сможет объяснить на примере условной семьи, зачем нужны резерв и сбережения, рассчитать размер резерва и различить акции и облигации как способы инвестирования.","criteria":["Я объясняю, зачем семье резерв и чем он отличается от сбережений на цель.","Я рассчитываю резерв на 3 месяца обязательных расходов.","Я объясняю разницу между акцией и облигацией по риску и доходу."],"result":"Схема «Деньги условной семьи»: распределение месячного дохода на расходы, резерв, сбережения и инвестиции с расчётом размера резерва и выбором инструмента (депозит, облигации, акции).","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Бюджет (budget)","real":"План доходов и расходов на период","shown":"План доходов и расходов на период","truth":true,"first":"Б"},{"term":"Резерв (подушка безопасности)","real":"Деньги на случай непредвиденных ситуаций, обычно 3–6 месяцев обязательных расходов","shown":"Долговая бумага: покупатель даёт деньги в долг компании или государству и получает фиксированный процент (купон), а в конце — возврат суммы","truth":false,"first":"Р"},{"term":"Сбережения","real":"Деньги, отложенные на конкретные цели","shown":"Деньги, отложенные на конкретные цели","truth":true,"first":"С"},{"term":"Инвестиции (investment)","real":"Вложение денег (money) ради дохода в будущем","shown":"Деньги на случай непредвиденных ситуаций, обычно 3–6 месяцев обязательных расходов","truth":false,"first":"И"},{"term":"Акция","real":"Доля в компании; доход зависит от успеха компании, цена может расти и падать","shown":"Доля в компании; доход зависит от успеха компании, цена может расти и падать","truth":true,"first":"А"},{"term":"Облигация","real":"Долговая бумага: покупатель даёт деньги в долг компании или государству и получает фиксированный процент (купон), а в конце — возврат суммы","shown":"Вложение денег (money) ради дохода в будущем","truth":false,"first":"О"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Бюджет (budget)","def":"План доходов и расходов на период"},{"term":"Резерв (подушка безопасности)","def":"Деньги на случай непредвиденных ситуаций, обычно 3–6 месяцев обязательных расходов"},{"term":"Сбережения","def":"Деньги, отложенные на конкретные цели"},{"term":"Инвестиции (investment)","def":"Вложение денег (money) ради дохода в будущем"},{"term":"Акция","def":"Доля в компании; доход зависит от успеха компании, цена может расти и падать"},{"term":"Облигация","def":"Долговая бумага: покупатель даёт деньги в долг компании или государству и получает фиксированный процент (купон), а в конце — возврат суммы"},{"term":"Обязательные расходы","def":"Траты, без которых не обойтись: жильё, коммунальные услуги, еда, проезд"}],"english":"budget — бюджет; investment — инвестиции; money — деньги","concepts":{"head":"Понятия","items":["Бюджет (budget) семьи — это доходы и расходы.","Разумная семья распределяет доход так: обязательные расходы → резерв (пока он не собран) → сбережения на цели → инвестиции (investment).","Резерв — для неожиданностей, сбережения — для целей, инвестиции — для роста денег (money) на долгий срок."]},"steps":{"head":"Как это работает, по шагам","items":["Посчитать обязательные расходы в месяц","Умножить на 3–6 — это размер резерва","Откладывать 10–20% дохода, пока резерв не собран","Хранить резерв там, где его можно быстро забрать (накопительный счёт, депозит без потери процентов при досрочном снятии)","После резерва — сбережения на цели и инвестиции. Облигации обычно спокойнее акций: процент известен заранее, но риск есть, если эмитент не сможет вернуть долг. Акции могут дать больше, но цена может упасть"]},"scheme":"«водопад дохода» — доход сверху стекает в чашу «обязательные расходы», затем «резерв», затем «цели», затем «инвестиции» (акции/облигации). Рядом таблица «Акция vs Облигация: что покупаю — доход — риск».","examples":[{"lab":"Казахстанский","text":"Казахстанский (условная семья): семья Сериковых в Таразе, доход 400 000 условных тенге, обязательные расходы 260 000. Резерв на 3 месяца: 260 000 × 3 = 780 000. Откладывая 15% дохода (60 000), они соберут его за 13 месяцев. В Казахстане государство выпускает облигации, которые можно купить через биржу KASE."},{"lab":"Мировой","text":"В США казначейские облигации считаются одним из самых надёжных инструментов, а акции крупных компаний за один год могут как вырасти, так и упасть на десятки процентов."}],"mistake":{"myth":"Путают резерв и сбережения на отпуск и тратят резерв на «хочу»","fix":"Разделите на доске «нужно срочно и неожиданно» и «хочу и запланировано»."},"check":[{"q":"Можно ли держать резерв в акциях?","a":"Нежелательно: в нужный момент они могут подешеветь"},{"q":"Чем облигация похожа на депозит?","a":"Даёшь деньги в долг под процент"},{"q":"Если резерв собран, что дальше?","a":"Цели и инвестиции"}],"kz":{"text":"Единый накопительный пенсионный фонд (ЕНПФ) Казахстана. ЕНПФ хранит пенсионные накопления казахстанцев, а Национальный банк инвестирует их, в том числе в государственные облигации.","link":"это пример долгосрочного инвестирования сбережений миллионов людей."},"world":{"text":"По данным международных исследований, значительная часть людей в мире не может без долгов покрыть неожиданный крупный расход, поэтому Всемирный банк и ОЭСР продвигают финансовую грамотность как важную часть устойчивого развития (ЦУР № 1 и № 8).","link":""},"fact":"Одна из старейших облигаций в мире, выпущенная голландским водным управлением в 1648 году на строительство дамбы, до сих пор приносит проценты; одна такая облигация хранится в Йельском университете, который периодически получает по ней купон.","cards":[{"n":"1","title":"Акция или облигация?","lines":["Утверждения: 1) Я стал совладельцем компании. 2) Мне вернут сумму через 3 года и будут платить 10% в год. 3) Мой доход зависит от прибыли компании. 4) Я дал деньги в долг государству."],"hand":"Сдать: ответы (1 — акция, 2 — облигация, 3 — акция, 4 — облигация).","answers":[]},{"n":"2","title":"Условная семья Ахметовых","lines":["Данные: доход семьи 350 000 условных тенге в месяц.","Расходы: жильё и коммунальные 90 000, еда 120 000, проезд 25 000, связь 10 000, одежда и прочее 45 000. Резерва пока нет. Цель — отпуск через год за 300 000.","Задание: 1) Посчитайте обязательные расходы (жильё, еда, проезд, связь) и резерв на 3 месяца. 2) Сколько остаётся в месяц после всех расходов? 3) Предложите распределение остатка между резервом и целью. 4) Где хранить резерв?"],"hand":"Сдать: схему «водопада»","answers":[["","Обязательные 245 000, резерв 735 000, остаток 60 000"]]},{"n":"3","title":"Олимпиадные задачи ФГиБ","lines":["Задача 1. Облигация номиналом 100 000 условных тенге приносит купон 11% годовых раз в год. Сколько получит владелец за 3 года и сколько всего вернётся в конце?","Задача 2. Обязательные расходы семьи 200 000 в месяц, семья откладывает 40 000 в месяц. За сколько месяцев она соберёт резерв на 4 месяца?"],"hand":"Сдать: решения.","answers":[["","Купоны 11 000 × 3 = 33 000; в конце — 100 000 номинала, всего 133 000."],["","800 000 ÷ 40 000 = 20 месяцев."]]}],"practice":[{"type":"case","title":"Миллионер-уборщик","minutes":10,"source":"Рональд Рид, Вермонт, США (умер в 2014 году)","hook":"Он работал на заправке и уборщиком. После смерти оказалось, что у него около 8 миллионов долларов.","story":["Рональд Рид всю жизнь прожил скромно в маленьком городе: работал на заправке, потом уборщиком в магазине.","Он ездил на старой машине и сам колол дрова. Никто не знал, что каждый месяц он откладывал часть зарплаты и покупал акции надёжных компаний.","Когда он умер в 2014 году, в завещании оказалось около 8 миллионов долларов — для местной больницы и библиотеки."],"question":"Что, по-вашему, главное в истории Рида?","options":["Ему просто повезло один раз","Он выиграл в лотерею","Он получил наследство","Регулярные небольшие вложения много лет и сложный процент"],"answerIndex":3,"reveal":"Рид не был богатым и не рисковал. Он десятилетиями вкладывал понемногу, не тратил дивиденды, а снова вкладывал их. Время и сложный процент сделали остальное.","teams":"Команды: семья может откладывать 20 000 тенге в месяц. Решите, на какую цель и куда: депозит, копилка, накопительный счёт. Объясните выбор.","takeaway":"Богатство строят не большие деньги, а регулярность и время."},{"type":"case","title":"Правило 72","minutes":8,"source":"Правило 72 — приём быстрого расчёта в финансах","hook":"Как без калькулятора понять, когда деньги удвоятся?","story":["Есть простое правило: раздели 72 на процент в год — получишь примерное число лет, за которое вклад удвоится с капитализацией.","Например, под 12% в год: 72 ÷ 12 = 6 лет.","Работает и наоборот: при инфляции 8% в год цены удвоятся примерно за 9 лет."],"question":"За сколько примерно лет удвоится вклад под 9% годовых с капитализацией?","options":["Никогда","Около 20 лет","Около 2 лет","Около 8 лет"],"answerIndex":3,"reveal":"72 ÷ 9 = 8 лет. Правило помогает быстро сравнивать: вклад или инфляция — что растёт быстрее? Если инфляция выше процента вклада, деньги теряют силу.","teams":"Команды: посчитайте по правилу 72 удвоение при 6%, 12%, 18%. Что выгоднее для цели «через 10 лет»?","takeaway":"Правило 72: делим 72 на процент — получаем годы до удвоения."}],"homework":"Составить личный «водопад» своих денег (карманные, подарки): сколько тратишь, сколько можно отложить в личный резерв и на цель; суммы условные.","support":"Шаблон «водопада» с готовыми чашами и формула «Резерв = обязательные расходы × 3».","advanced":"Сравнить для условной семьи облигацию с купоном 12% годовых и депозит под 11%: какой доход на 500 000 за год и какой риск у каждого варианта.","photo":{"src":"lessons/img/08_22.jpg","author":"Jimmy Dean","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему резерв защищает не только семью, но и экономику страны от кризисов?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g08-l22.pptx","name":"22. Семейный бюджет и инвестирование (8 кл).pptx","mb":1.5}},{"id":"08_23","g":8,"l":23,"topic":"Семейный бюджет и инвестирование: практикум","module":"Бюджетирование (личные финансы)","format":"Проектная мастерская","skills":["Финансовое мышление","Командная работа","Креативность"],"goal":"К концу урока ученик сможет рассчитать, во что превратятся ежемесячные сбережения условной семьи за 3 года по простому и сложному проценту, и объяснить, откуда берётся разница.","criteria":["Я правильно считаю проценты по простой схеме: только на внесённые деньги.","Я правильно считаю сложный процент: проценты прибавляются к сумме и в следующем году тоже приносят доход.","Я объясняю разницу и делаю вывод для семьи."],"result":"Командная таблица-расчёт «Сбережения семьи за 3 года»: взносы, проценты по простой и сложной схеме по годам, итог и вывод о разнице.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Бюджет (budget)","real":"План доходов и расходов семьи","shown":"План доходов и расходов семьи","truth":true,"first":"Б"},{"term":"Инвестиции (investment)","real":"Вложение денег (money) ради дохода в будущем","shown":"Сколько процентов в год приносит вклад","truth":false,"first":"И"},{"term":"Актив","real":"То, что приносит доход или сохраняет стоимость: вклад, облигация, акция","shown":"То, что приносит доход или сохраняет стоимость: вклад, облигация, акция","truth":true,"first":"А"},{"term":"Простой процент","real":"Проценты начисляются только на внесённую сумму и не прибавляются к ней","shown":"Вложение денег (money) ради дохода в будущем","truth":false,"first":"П"},{"term":"Сложный процент (капитализация)","real":"Проценты прибавляются к сумме, и на них тоже начисляются проценты","shown":"Проценты прибавляются к сумме, и на них тоже начисляются проценты","truth":true,"first":"С"},{"term":"Годовая ставка","real":"Сколько процентов в год приносит вклад","shown":"Проценты начисляются только на внесённую сумму и не прибавляются к ней","truth":false,"first":"Г"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Бюджет (budget)","def":"План доходов и расходов семьи"},{"term":"Инвестиции (investment)","def":"Вложение денег (money) ради дохода в будущем"},{"term":"Актив","def":"То, что приносит доход или сохраняет стоимость: вклад, облигация, акция"},{"term":"Простой процент","def":"Проценты начисляются только на внесённую сумму и не прибавляются к ней"},{"term":"Сложный процент (капитализация)","def":"Проценты прибавляются к сумме, и на них тоже начисляются проценты"},{"term":"Годовая ставка","def":"Сколько процентов в год приносит вклад"},{"term":"Практика (practice)","def":"Применение формул на реальной задаче"}],"english":"budget — бюджет; investment — инвестиции; money — деньги; practice — практика","concepts":{"head":"Понятия","items":["Вклад — актив семьи.","Простой процент: доход = сумма × ставка, проценты «откладываются в сторону».","Сложный процент: доход прибавляется к сумме, и на следующий год проценты считаются уже на увеличенную сумму.","В расчётах используем упрощение: 12 месячных взносов вносятся как одна сумма в начале года, проценты начисляются в конце года."]},"steps":{"head":"Как считать, по шагам","items":["Годовой взнос = месячный × 12","Простой процент: в каждом году проценты = (все внесённые деньги) × ставка; итог = взносы + сумма процентов","Сложный: остаток на начало года + взнос → умножаем на (1 + ставка) → это остаток на конец года; повторяем 3 раза","Сравниваем итоги"]},"scheme":"Две лестницы по 3 ступени. Левая «Простой %» — ступени одинаковой «надбавки». Правая «Сложный %» — каждая следующая надбавка выше. Под ними формула «Конец года = (Начало + Взнос) × (1 + ставка)».","examples":[{"lab":"Казахстанский","text":"Казахстанский (условная семья из Алматы): откладывает 20 000 условных тенге в месяц (240 000 в год), ставка 10% годовых. Простой: проценты 24 000 + 48 000 + 72 000 = 144 000; итог 720 000 + 144 000 = 864 000. Сложный: год 1 — 240 000 × 1,1 = 264 000; год 2 — (264 000 + 240 000) × 1,1 = 554 400; год 3 — (554 400 + 240 000) × 1,1 = 873 840. Разница 9 840 — это «проценты на проценты»."},{"lab":"Мировой","text":"Инвесторы считают сложный процент главным двигателем роста долгосрочных сбережений."}],"mistake":{"myth":"При сложном проценте забывают прибавить новый взнос перед умножением","fix":"Пусть команда проговаривает вслух «начало + взнос, потом умножаем»."},"check":[{"q":"Почему за 1 год простой и сложный дают одинаково?","a":"Ещё не начислялись проценты на проценты"},{"q":"Что увеличит разницу?","a":"Дольше срок, выше ставка, больше взнос"},{"q":"Есть ли риск у вклада?","a":"Низкий; у акций выше"}],"kz":{"text":"Otbasy Bank. Казахстанский банк жилищных строительных сбережений предлагает гражданам годами регулярно откладывать деньги на жильё; к накоплениям начисляются вознаграждение и государственная премия.","link":"это реальный пример того, как регулярные взносы и проценты за несколько лет превращаются в крупную сумму."},"world":{"text":"Во многих странах государства поощряют долгосрочные сбережения граждан (пенсионные и образовательные счета), потому что сложный процент за десятилетия заметно увеличивает накопления.","link":""},"fact":"Идея сложных процентов была известна ещё в древности, а в эпоху Возрождения итальянский математик Лука Пачоли в книге 1494 года описал «правило 72»: чтобы узнать, за сколько лет сумма удвоится, нужно разделить 72 на годовую ставку в процентах.","cards":[{"n":"1","title":"Условные семьи (каждой команде одна; упрощение: годовой взнос вносится в начале года, проценты — в конце)","lines":["Семья А: 20 000 в месяц, ставка 10%.","Семья Б: 15 000 в месяц, ставка 12%.","Семья В: 25 000 в месяц, ставка 8%.","Задание: заполните таблицу по 3 годам для простого и сложного процента, найдите разницу и напишите вывод из 2 предложений для семьи."],"hand":"Сдать: таблицу (ключ у тренера).","answers":[["","Простой — 864 000; сложный — 873 840; разница 9 840."],["","Простой — 669 600; сложный — около 680 279; разница около 10 679."],["","Простой — 900 000 + 144 000 = 1 044 000; сложный — около 1 051 834; разница около 7 834."]]},{"n":"2","title":"Олимпиадные задачи ФГиБ","lines":["Задача 1. Вклад 100 000 условных тенге на 2 года под 10% годовых. Сколько будет при простом и при сложном проценте?","Задача 2. Какой вклад выгоднее на 2 года для 200 000: А — 12% годовых простой процент; Б — 11% годовых с ежегодной капитализацией?"],"hand":"Сдать: решения.","answers":[["","Простой — 120 000; сложный — 100 000 × 1,1 × 1,1 = 121 000."],["","А — 248 000; Б — 200 000 × 1,11 × 1,11 = 246 420; выгоднее А."]]},{"n":"3","title":"Открытка из будущего","lines":["Задание: «Через три года моя семья рада, что сегодня я … Действие на 48 часов: …»"],"hand":"Сдать: вслух только действие.","answers":[]}],"practice":[{"type":"case","title":"Завещание Франклина на 200 лет","minutes":10,"source":"Бенджамин Франклин, завещание Бостону и Филадельфии, 1790–1990","hook":"Франклин оставил двум городам небольшую сумму с условием: не трогать 200 лет.","story":["Бенджамин Франклин, один из основателей США, умер в 1790 году.","В завещании он оставил Бостону и Филадельфии по 1000 фунтов. Деньги нужно было давать в долг молодым ремесленникам под проценты.","Часть суммы можно было тратить через 100 лет, а остальное — только через 200 лет."],"question":"Что, по-вашему, случилось с деньгами через 200 лет?","options":["Они исчезли","Стали в 10 раз меньше","Они выросли до нескольких миллионов долларов","Остались те же 1000 фунтов"],"answerIndex":2,"reveal":"К 1990 году фонды выросли до нескольких миллионов долларов. Это пример силы сложного процента на очень долгом сроке. Время — главный союзник инвестора.","teams":"Команды: семья кладёт 100 000 тенге под условные 10% годовых с капитализацией. Посчитайте сумму через 1, 2 и 3 года.","takeaway":"На длинном сроке сложный процент творит чудеса."},{"type":"case","title":"Семья Ахметовых планирует отпуск","minutes":8,"source":"Условная ситуация","hook":"Доход семьи 600 000 тенге. Отпуск стоит 480 000. Как накопить за год?","story":["Семья Ахметовых: доход 600 000 тенге в месяц. Обязательные расходы — 450 000 (еда, коммуналка, транспорт, кредит).","Ещё 100 000 уходит на «разное»: кафе, подписки, покупки.","Летом семья хочет поехать в отпуск за 480 000 тенге."],"question":"Сколько нужно откладывать в месяц, чтобы за 12 месяцев накопить на отпуск?","options":["4 800 тенге","100 000 тенге","40 000 тенге","480 000 тенге"],"answerIndex":2,"reveal":"480 000 ÷ 12 = 40 000 тенге в месяц. Свободно остаётся 600 000 − 450 000 = 150 000, из них 100 000 на «разное». Достаточно сократить «разное» на 40 000 — и цель достижима.","teams":"Команды: составьте бюджет Ахметовых: доходы, обязательные, накопления на отпуск, подушка, «разное».","takeaway":"Большая цель делится на понятный ежемесячный платёж."}],"homework":"Продлить расчёт своей семьи до 5 лет по сложному проценту и посчитать, во сколько раз выросла разница по сравнению с 3 годами.","support":"Таблица с готовыми строками «Начало — Взнос — Сумма — × ставка — Конец» и первым годом, посчитанным как образец.","advanced":"Проверить «правило 72» на ставке 12%: за сколько лет удвоится сумма, и сравнить с расчётом по годам.","photo":{"src":"lessons/img/08_23.jpg","author":"Jimmy Dean","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему для сложного процента время важнее, чем размер стартовой суммы?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g08-l23.pptx","name":"23. Семейный бюджет и инвестирование — практикум (8 кл).pptx","mb":1.5}},{"id":"08_24","g":8,"l":24,"topic":"Как защитить себя от фин. мошенников","module":"Бюджетирование (личные финансы)","format":"Питч и защита","skills":["Финансовое мышление","Презентация"],"goal":"К концу урока ученик сможет назвать 3 схемы финансового мошенничества (звонок «службы безопасности банка», сообщение «друга» с просьбой о деньгах, «лёгкий заработок» или пирамида), перечислить признаки каждой и защитить в питче правило защиты.","criteria":["Я говорю ясно и укладываюсь в 2 минуты.","В питче есть проблема (схема), признаки и решение (правило защиты).","Я отвечаю на вопрос «инвестора» по теме."],"result":"Командный питч на 1–2 минуты по шаблону «Что? Кому? Как?»: одна схема мошенничества, 3 её признака и правило защиты для сверстников.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Подготовка","min":6},{"stage":"Питчи","min":20},{"stage":"Голосование","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Мошенничество (fraud)","real":"Получение чужих денег (money) или данных путём обмана","shown":"Получение чужих денег (money) или данных путём обмана","truth":true,"first":"М"},{"term":"Финансовое мошенничество","real":"Обман, связанный с деньгами, картами, вкладами, инвестициями","shown":"Код подтверждения операции, который нельзя сообщать никому","truth":false,"first":"Ф"},{"term":"Социальная инженерия","real":"Приёмы, когда мошенник давит на эмоции (спешка, страх, жадность), чтобы человек сам отдал данные или деньги","shown":"Приёмы, когда мошенник давит на эмоции (спешка, страх, жадность), чтобы человек сам отдал данные или деньги","truth":true,"first":"С"},{"term":"Фишинг","real":"Поддельные сайты и ссылки, похожие на настоящие, чтобы украсть пароль или данные карты","shown":"Обман, связанный с деньгами, картами, вкладами, инвестициями","truth":false,"first":"Ф"},{"term":"Финансовая пирамида","real":"Схема, где «доход» старым участникам платят из денег новых участников","shown":"Схема, где «доход» старым участникам платят из денег новых участников","truth":true,"first":"Ф"},{"term":"Одноразовый код (SMS-код)","real":"Код подтверждения операции, который нельзя сообщать никому","shown":"Поддельные сайты и ссылки, похожие на настоящие, чтобы украсть пароль или данные карты","truth":false,"first":"О"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Мошенничество (fraud)","def":"Получение чужих денег (money) или данных путём обмана"},{"term":"Финансовое мошенничество","def":"Обман, связанный с деньгами, картами, вкладами, инвестициями"},{"term":"Социальная инженерия","def":"Приёмы, когда мошенник давит на эмоции (спешка, страх, жадность), чтобы человек сам отдал данные или деньги"},{"term":"Фишинг","def":"Поддельные сайты и ссылки, похожие на настоящие, чтобы украсть пароль или данные карты"},{"term":"Финансовая пирамида","def":"Схема, где «доход» старым участникам платят из денег новых участников"},{"term":"Одноразовый код (SMS-код)","def":"Код подтверждения операции, который нельзя сообщать никому"}],"english":"fraud — мошенничество; money — деньги","concepts":{"head":"Понятия","items":["Мошенничество (fraud) — получение денег (money) обманом.","Почти все схемы используют три рычага: спешка («срочно!»), эмоции (страх или жадность) и просьба сообщить данные или перевести деньги."]},"steps":{"head":"Три схемы и их признаки, по шагам","items":["А) «Служба безопасности банка»: звонят, сообщают о «подозрительной операции», просят назвать код из SMS или перевести деньги на «безопасный счёт»","Признаки: звонок сам, срочность, просьба о коде","Защита: положить трубку и самому позвонить по номеру на обороте карты","Б) «Друг просит в долг»: сообщение со взломанного аккаунта друга: «Срочно скинь 10 000, потом объясню»","Признаки: необычный стиль, спешка, новые реквизиты","Защита: позвонить другу голосом","В) «Лёгкий заработок» / пирамида: обещают 30% в месяц без риска, просят привести друзей","Признаки: гарантированный высокий доход, оплата за привлечение людей, нет лицензии","Защита: проверить организацию в реестре финансового регулятора"]},"scheme":"Треугольник «Спешка — Эмоции — Просьба о деньгах/данных» в центре; вокруг три карточки схем с признаками; внизу «Стоп-правило: остановись → проверь сам по официальному каналу → посоветуйся со взрослым».","examples":[{"lab":"Казахстанский","text":"Аружан из Усть-Каменогорска получила сообщение «Вы выиграли телефон, оплатите доставку 3 000 условных тенге по ссылке» — это фишинг. В Казахстане регулятор финансового рынка (АРРФР) публикует предупреждения о финансовых пирамидах."},{"lab":"Мировой","text":"В 1920 году в США Чарльз Понци обещал вкладчикам 50% за 45 дней и платил старым участникам деньгами новых — его имя стало названием схемы."}],"mistake":{"myth":"«я умный, меня не обманут»","fix":"Покажите, что мошенники рассчитывают именно на спешку, а не на глупость, и отработайте правило паузы."},"check":[{"q":"Может ли банк попросить SMS-код по телефону?","a":"Нет"},{"q":"Почему пирамида рано или поздно рушится?","a":"Новых участников становится не хватать"},{"q":"Что делать, если данные уже сообщил?","a":"Сразу позвонить в банк по официальному номеру и заблокировать карту, сказать взрослым"}],"kz":{"text":"Агентство РК по регулированию и развитию финансового рынка (АРРФР). Агентство контролирует банки и другие финансовые организации и регулярно предупреждает граждан о финансовых пирамидах и мошеннических схемах.","link":"перед вложением денег можно проверить, есть ли у организации лицензия."},"world":{"text":"Мошенничество в интернете — глобальная проблема: поддельные сайты и звонки приходят из разных стран, поэтому банки и полиция сотрудничают на международном уровне, а ЦУР № 16 говорит о борьбе с финансовыми преступлениями.","link":""},"fact":"В 1920 году Чарльз Понци в Бостоне обещал инвесторам 50% прибыли за 45 дней и за несколько месяцев собрал миллионы долларов; схема рухнула, когда новые вкладчики перестали приходить. С тех пор финансовые пирамиды называют «схемой Понци».","cards":[{"n":"1","title":"Схемы для команд","lines":["Схема А. Звонок: «Здравствуйте, служба безопасности банка. С вашей карты пытаются списать деньги. Назовите код из SMS, чтобы отменить операцию».","Схема Б. Сообщение от «друга»: «Привет, срочно нужно 10 000, скинь на эту карту, вечером верну, не звони, я на уроке».","Схема В. Реклама: «Вложи 20 000 — получай 30% в месяц без риска! Приведи 3 друзей — бонус 5 000!»","Задание: найдите 3 признака обмана и придумайте правило защиты."],"hand":"Сдать: план питча.","answers":[]},{"n":"2","title":"Шаблон питча «Что? Кому? Как?»","lines":["Что: какая схема и как она выглядит (20 секунд). Кому: кто чаще всего попадается и почему (20 секунд). Как: 3 признака и правило защиты (60 секунд). Финал: одна фраза-слоган."],"hand":"Сдать: выступление 1–2 минуты.","answers":[]},{"n":"3","title":"Олимпиадные задачи ФГиБ","lines":["Задача 1. «Инвестиционный клуб» обещает 30% в месяц от вложения. Ерлан вложил 50 000 условных тенге. Сколько ему обещают выплатить за 3 месяца (простой процент) и почему это признак пирамиды?","Задача 2. В пирамиде каждый участник должен привести 5 новых. На 1-м уровне 1 человек. Сколько людей нужно на 7-м уровне?"],"hand":"Сдать: ответы на листке.","answers":[["","50 000 × 0,3 × 3 = 45 000; такая гарантированная доходность нереальна для честных вложений, выплаты возможны только из денег новых участников."],["","5⁶ = 15 625 человек, а на 10-м уровне — 1 953 125; схема быстро упирается в нехватку людей."]]}],"practice":[{"type":"case","title":"Почтовые купоны Понци","minutes":10,"source":"Чарльз Понци, Бостон, США, 1920","hook":"Обещал +50% за 45 дней. Тысячи людей отдали ему деньги.","story":["В 1920 году Чарльз Понци обещал вкладчикам 50% прибыли за 45 дней.","Он рассказывал, что зарабатывает на разнице цен международных почтовых купонов в разных странах.","Первые вкладчики действительно получали деньги — и рассказывали знакомым."],"question":"Откуда, по-вашему, на самом деле Понци брал деньги для выплат?","options":["Из банка","Из своей зарплаты","Из прибыли на купонах","Из денег новых вкладчиков"],"answerIndex":3,"reveal":"Понци платил старым вкладчикам деньгами новых. Когда новых стало мало, схема рухнула, а тысячи людей потеряли деньги. С тех пор такие схемы называют «схемами Понци» или пирамидами.","teams":"Команды: составьте список из 5 признаков финансовой пирамиды.","takeaway":"Высокий гарантированный доход + «приводи друзей» = пирамида."},{"type":"case","title":"МММ","minutes":9,"source":"Финансовая пирамида «МММ» Сергея Мавроди, Россия, 1994","hook":"Реклама по телевизору, «акции», которые росли каждую неделю. Что случилось?","story":["В 1994 году по телевидению постоянно показывали рекламу «МММ» с героем Лёней Голубковым.","«Акции» МММ росли в цене почти каждый день, их покупали миллионы людей.","Цену назначал сам Мавроди, а реального бизнеса, который приносил бы прибыль, не было."],"question":"Почему, по-вашему, «акции» росли, если бизнеса не было?","options":["Компания много зарабатывала","Государство поддерживало","Цену просто объявлял владелец, а выплаты шли за счёт новых покупателей","Росла нефть"],"answerIndex":2,"reveal":"Летом 1994 года пирамида рухнула, миллионы людей потеряли деньги. Позже Мавроди осудили. Даже большая реклама по ТВ не гарантирует, что компания честная.","teams":"Команды: проверьте 3 «объявления об инвестициях» по признакам пирамиды.","takeaway":"Реклама и рост цены — не доказательство честности."}],"homework":"Рассказать о 3 признаках мошенничества одному взрослому и одному младшему члену семьи и записать, какой вопрос они задали.","support":"Шаблон питча с началами фраз: «Представьте, вам пишут…», «Три признака…», «Наше правило…»; список признаков для выбора.","advanced":"Добавить в питч расчёт: сколько участников нужно пирамиде на 7-м уровне, если каждый приводит 5 человек, и объяснить, почему схема неизбежно рушится.","photo":{"src":"lessons/img/08_24.jpg","author":"Hassan OUAJBIR","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему одна страна не может победить интернет-мошенников в одиночку?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g08-l24.pptx","name":"24. Как защитить себя от фин. мошенников (8 кл).pptx","mb":1.5}},{"id":"08_25","g":8,"l":25,"topic":"Ярмарка: прибыль и резерв","module":"Бюджетирование (личные финансы)","format":"Симуляция, ярмарка","skills":["Финансовое мышление","Работа с клиентом"],"goal":"К концу урока ученик сможет выполнить свою роль на учебной ярмарке, рассчитать прибыль команды и распределить её по правилу: резерв на риски, вложение в следующий товар и итоговый результат.","criteria":["Я рассчитываю цену так, что каждая продажа даёт прибыль, и объясняю выгоду товара для покупателя.","Я выполняю свою роль и веду учёт продаж без ошибок.","Я правильно считаю прибыль и резерв и объясняю, зачем бизнесу резерв."],"result":"План команды на ярмарку (товар, себестоимость, цена, роли, оформление) и расчёт после торговли: выручка, расходы, прибыль, резерв 20% и решение, куда направить остаток.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Ярмарка (fair)","real":"Ивент, где команды продают товары покупателям","shown":"Ивент, где команды продают товары покупателям","truth":true,"first":"Я"},{"term":"Выручка","real":"Все деньги (money) от продаж","shown":"Разница между ценой продажи и себестоимостью","truth":false,"first":"В"},{"term":"Себестоимость","real":"Сколько стоит изготовить или закупить одну единицу товара","shown":"Сколько стоит изготовить или закупить одну единицу товара","truth":true,"first":"С"},{"term":"Прибыль (profit)","real":"Выручка минус все расходы","shown":"Все деньги (money) от продаж","truth":false,"first":"П"},{"term":"Резерв","real":"Часть прибыли, которую откладывают на непредвиденные расходы и риски бизнеса","shown":"Часть прибыли, которую откладывают на непредвиденные расходы и риски бизнеса","truth":true,"first":"Р"},{"term":"Наценка","real":"Разница между ценой продажи и себестоимостью","shown":"Выручка минус все расходы","truth":false,"first":"Н"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ярмарка (fair)","def":"Ивент, где команды продают товары покупателям"},{"term":"Выручка","def":"Все деньги (money) от продаж"},{"term":"Себестоимость","def":"Сколько стоит изготовить или закупить одну единицу товара"},{"term":"Прибыль (profit)","def":"Выручка минус все расходы"},{"term":"Резерв","def":"Часть прибыли, которую откладывают на непредвиденные расходы и риски бизнеса"},{"term":"Наценка","def":"Разница между ценой продажи и себестоимостью"},{"term":"Точка безубыточности","def":"Количество продаж, при котором выручка равна расходам"}],"english":"fair — ярмарка; profit — прибыль; money — деньги","concepts":{"head":"Понятия","items":["Прибыль (profit) = выручка − расходы.","Разумный бизнес, как и семья, не тратит всю прибыль, а откладывает резерв: на риски (порча товара, возврат, снижение спроса) и на развитие.","На нашей ярмарке (fair) правило: 20% прибыли — в резерв."]},"steps":{"head":"Как работаем, по шагам","items":["Считаем себестоимость единицы","Назначаем цену с наценкой, проверяя, что покупателю выгодно","Находим точку безубыточности: так как весь товар закупаем заранее, считаем «все стартовые расходы ÷ цена» — столько продаж вернут вложенные деньги","Торгуем и ведём учёт","Считаем выручку, расходы, прибыль","20% — в резерв, остаток — решение команды: вложить в товар для следующей ярмарки или зафиксировать результат"]},"scheme":"«путь денег ярмарки»: Стартовый бюджет → Закупка (себестоимость) → Продажи (выручка) → Прибыль → развилка «Резерв 20% | Развитие | Итог». Рядом формулы прибыли и точки безубыточности.","examples":[{"lab":"Казахстанский","text":"Команда 8 класса в Кызылорде делает брелоки: материалы на 20 штук стоят 4 000 условных тенге (себестоимость 200), цена 500. Точка безубыточности: 4 000 ÷ 500 = 8 продаж. Продали 16: выручка 8 000, прибыль 4 000, резерв 20% = 800, остаток 3 200."},{"lab":"Мировой","text":"Крупные компании формируют резервный капитал из прибыли, чтобы пережить кризисные годы."}],"mistake":{"myth":"Команда считает прибылью всю выручку и «тратит» её","fix":"Сначала вычесть расходы, затем резерв, и только остаток — свободные деньги."},"check":[{"q":"Если продали 6 брелоков, есть ли прибыль?","a":"Нет: выручка 3 000 < расходов 4 000, убыток 1 000"},{"q":"Зачем резерв, если ярмарка уже прошла?","a":"На следующую ярмарку и на риски"},{"q":"Как скидка влияет на прибыль?","a":"Уменьшает прибыль с каждой продажи"}],"kz":{"text":"Kaspi.kz и малый бизнес. Через Kaspi Магазин и Kaspi Pay многие небольшие казахстанские предприниматели продают товары и принимают оплату.","link":"каждый такой продавец считает себестоимость, наценку и прибыль и решает, сколько вложить в новый товар."},"world":{"text":"Многие международные компании после кризисов (например, пандемии 2020 года) стали держать больший резерв денег, потому что без него бизнесу трудно пережить внезапное падение продаж.","link":""},"fact":"Во время Великой депрессии 1929–1933 годов в США разорились тысячи банков и компаний, а продажи многих фирм резко упали. С тех пор финансисты повторяют правило: бизнесу нужен резерв денег на трудные времена, а не только прибыль в хорошие.","cards":[{"n":"1","title":"План команды","lines":["Данные: стартовый бюджет 5 000 условных тенге. Варианты товара: брелоки (себестоимость 200), закладки (100), открытки (250). Расходы на оформление прилавка — 500.","Задание: выберите товар и количество, назначьте цену, посчитайте точку безубыточности (все расходы ÷ цена), распределите роли: закупщик, продавец, кассир, учётчик, финансовый директор."],"hand":"Сдать: план на А4.","answers":[]},{"n":"2","title":"События рынка","lines":["1) Покупатель просит скидку 20% за 3 товара. 2) 2 брелока оказались бракованными. 3) Конкурент снизил цену. 4) «Оптовик» хочет 6 штук по сниженной цене. 5) Налетели покупатели — очередь.","Задание: за 30 секунд решите, как действовать, запишите влияние на прибыль."],"hand":"Сдать: записи вместе с учётом.","answers":[]},{"n":"3","title":"Олимпиадные задачи ФГиБ","lines":["Задача 1. Команда закупила 25 закладок по 120 условных тенге и потратила 500 на оформление. Продала 20 закладок по 300. Найдите прибыль и резерв 20%.","Задача 2. Расходы команды 4 500 условных тенге, цена товара 450. Сколько нужно продать, чтобы выйти в ноль?"],"hand":"Сдать: решения.","answers":[["","Расходы 3 000 + 500 = 3 500; выручка 6 000; прибыль 2 500; резерв 500."],["","4 500 ÷ 450 = 10 штук."]]}],"practice":[{"type":"case","title":"Резерв, который спас компанию","minutes":9,"source":"Условная ситуация на основе обычной практики бизнеса","hook":"Команда заработала прибыль. Потратить всё или оставить резерв?","story":["На прошлой ярмарке команда 8 класса заработала 30 000 тенге прибыли.","Одни предлагают потратить всё на пиццу, другие — оставить часть на следующую ярмарку.","Перед следующей ярмаркой подорожали материалы, а один покупатель вернул товар."],"question":"Какое решение лучше для команды?","options":["Взять ещё и в долг","Потратить всё сразу","Отложить часть прибыли в резерв на материалы и непредвиденное","Раздать всё поровну и забыть"],"answerIndex":2,"reveal":"Резерв — это «подушка» бизнеса. Он позволяет купить материалы, вернуть деньги покупателю или пережить плохой день, не залезая в долги. Обычно часть прибыли откладывают, а часть распределяют.","teams":"Команды: распределите прибыль 30 000 тенге: резерв, вознаграждение команде, развитие. Обоснуйте проценты.","takeaway":"Часть прибыли — всегда в резерв."},{"type":"case","title":"Как Apple спаслась в 1997","minutes":8,"source":"Apple и инвестиция Microsoft, август 1997","hook":"Компании оставалось денег на несколько месяцев. Кто помог?","story":["В 1997 году у Apple были большие убытки, и ходили слухи, что компания скоро закроется.","Стив Джобс, вернувшийся в компанию, договорился о неожиданной сделке.","Помощь пришла от главного конкурента."],"question":"Кто вложил деньги в Apple в 1997 году?","options":["Никто, Apple закрылась","Государство США","Samsung","Microsoft — 150 миллионов долларов"],"answerIndex":3,"reveal":"Microsoft вложила 150 миллионов долларов, и это помогло Apple пережить трудное время. Без резерва даже известная компания может оказаться на грани. Позже Apple стала одной из самых богатых компаний мира и держит огромные резервы.","teams":"Команды: что будет с вашим ярмарочным бизнесом, если следующая ярмарка провалится? Хватит ли резерва?","takeaway":"Компании без резерва приходится просить помощи даже у конкурентов."}],"homework":"Посчитать, как изменилась бы прибыль команды при цене на 100 условных тенге выше и при продаже на 20% меньше единиц; сделать вывод о цене.","support":"Готовый бланк расчёта с формулами в строках; роль помощника кассира с понятным алгоритмом учёта.","advanced":"Роль финансового директора: вести расчёт прибыли в реальном времени и после первой смены предложить изменение цены на основе точки безубыточности.","photo":{"src":"lessons/img/08_25.jpg","author":"Jonathan Borba","q":["Что вы видите на фото? Как это связано с нашей темой?","Какой минимальный резерв нужен нашей ярмарочной команде и почему?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g08-l25.pptx","name":"25. Ярмарка — прибыль и резерв (8 кл).pptx","mb":1.8}},{"id":"08_26","g":8,"l":26,"topic":"Как защитить себя от фин. мошенников: практикум","module":"Бюджетирование (личные финансы)","format":"Питч и защита","skills":["Финансовое мышление","Презентация"],"goal":"К концу урока ученик сможет распознать мошенничество в 5 сообщениях (включая предложение финансовой пирамиды), указать в каждом признаки обмана и показать правильный ответ или действие.","criteria":["Я говорю ясно и укладываюсь во время.","Я называю проблему (схему), признаки и правильное действие для каждого сообщения.","Я уверенно отвечаю на вопрос и показываю, как отказать мошеннику."],"result":"Лист «Разбор 5 сообщений» (мошенничество или нет, признаки, правильное действие) и командный питч на 1–2 минуты по шаблону «Что? Кому? Как?» с разыгранным правильным ответом на одно сообщение.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Подготовка","min":6},{"stage":"Питчи","min":20},{"stage":"Голосование","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Мошенничество (fraud)","real":"Получение чужих денег (money) или данных обманом","shown":"Получение чужих денег (money) или данных обманом","truth":true,"first":"М"},{"term":"Финансовая пирамида","real":"Схема, где «доход» участникам платят из взносов новых участников, а не из реального бизнеса","shown":"Отработка действий на учебных ситуациях","truth":false,"first":"Ф"},{"term":"Фишинговая ссылка","real":"Ссылка на поддельный сайт, который копирует банк, магазин или госуслуги","shown":"Ссылка на поддельный сайт, который копирует банк, магазин или госуслуги","truth":true,"first":"Ф"},{"term":"Официальный канал","real":"Номер телефона на обороте карты, официальное приложение или сайт, которые ты находишь сам","shown":"Схема, где «доход» участникам платят из взносов новых участников, а не из реального бизнеса","truth":false,"first":"О"},{"term":"Лицензия","real":"Разрешение государства на финансовую деятельность","shown":"Разрешение государства на финансовую деятельность","truth":true,"first":"Л"},{"term":"Практика (practice)","real":"Отработка действий на учебных ситуациях","shown":"Номер телефона на обороте карты, официальное приложение или сайт, которые ты находишь сам","truth":false,"first":"П"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Мошенничество (fraud)","def":"Получение чужих денег (money) или данных обманом"},{"term":"Финансовая пирамида","def":"Схема, где «доход» участникам платят из взносов новых участников, а не из реального бизнеса"},{"term":"Фишинговая ссылка","def":"Ссылка на поддельный сайт, который копирует банк, магазин или госуслуги"},{"term":"Официальный канал","def":"Номер телефона на обороте карты, официальное приложение или сайт, которые ты находишь сам"},{"term":"Лицензия","def":"Разрешение государства на финансовую деятельность"},{"term":"Практика (practice)","def":"Отработка действий на учебных ситуациях"}],"english":"fraud — мошенничество; money — деньги; practice — практика","concepts":{"head":"Понятия","items":["Мошенничество (fraud) почти всегда содержит три сигнала: спешку, сильные эмоции (страх, радость, жадность) и просьбу перевести деньги (money), назвать код или перейти по ссылке.","Финансовая пирамида — отдельная схема: обещает высокий гарантированный доход и платит за привлечение новых людей."]},"steps":{"head":"Как проверять сообщение, по шагам","items":["Кто пишет и через какой канал?","Есть ли спешка или давление?","Просят ли деньги, код, данные карты, перейти по ссылке?","Обещают ли выигрыш или доход «без риска»?","Проверить через официальный канал или голосом","Если сомневаешься — не отвечать, посоветоваться со взрослым. Признаки пирамиды: доход выше, чем у банков, «гарантирован»; вознаграждение за приглашение друзей; нет лицензии регулятора; непонятно, на чём зарабатывают"]},"scheme":"«детектор сообщения» из 5 вопросов: Кто? Срочно? Просят деньги/код/ссылку? Обещают сверхдоход? Проверил по официальному каналу? Если хотя бы 2 «тревожных» ответа — стоп.","examples":[{"lab":"Казахстанский","text":"Нурлан из Шымкента получил сообщение «Ваш посылка задержана, оплатите 500 условных тенге за хранение по ссылке» — ошибка в тексте, ссылка не с официального сайта почты, срочность. Правильное действие: не переходить, проверить трек-номер в официальном приложении. В Казахстане создание финансовой пирамиды — уголовное преступление."},{"lab":"Мировой","text":"В 2008 году в США раскрыли пирамиду Бернарда Мэдоффа, которая десятилетиями выплачивала «доход» за счёт новых вкладчиков."}],"mistake":{"myth":"Ученики проверяют только «странную ссылку» и пропускают давление и просьбу кода","fix":"Проходим по всем 5 вопросам детектора для каждого сообщения."},"check":[{"q":"Сообщение от друга с просьбой денег — всегда мошенничество?","a":"Нет, но проверить нужно голосом"},{"q":"Почему пирамида платит первым участникам?","a":"Чтобы они привлекли новых"},{"q":"Что делать, если уже перевёл деньги?","a":"Сразу позвонить в банк по официальному номеру и сообщить в полицию, рассказать взрослым"}],"kz":{"text":"Регулятор финансового рынка Казахстана (АРРФР) и предупреждения о пирамидах. Агентство публикует информацию о признаках финансовых пирамид и предупреждает граждан о нелегальных «инвестиционных» проектах; создание и руководство финансовой пирамидой в Казахстане преследуется по уголовному закону.","link":""},"world":{"text":"Пирамида Бернарда Мэдоффа, раскрытая в 2008 году в США, стала одной из крупнейших в истории: пострадали инвесторы и благотворительные фонды из разных стран. Это показало, что даже опытные люди попадаются на «стабильно высокий доход».","link":""},"fact":"Бернард Мэдофф был бывшим председателем совета директоров биржи NASDAQ, и именно доверие к его репутации помогало пирамиде работать десятилетиями; в 2009 году он был приговорён к 150 годам заключения.","cards":[{"n":"1","title":"Пять сообщений","lines":["1) «Здравствуйте! Служба безопасности банка. С вашей карты пытаются списать 80 000. Продиктуйте код из SMS, чтобы отменить операцию».","2) «Мама, у меня новый номер, телефон разбился. Срочно переведи 15 000 на эту карту, потом объясню».","3) «Поздравляем! Вы выиграли смартфон. Оплатите доставку 2 000 по ссылке до 18:00».","4) «Клуб инвесторов: вложи 50 000 — получай 25% в месяц гарантированно. Приведи 3 друзей — бонус 10 000».","5) Уведомление в официальном приложении банка: «Покупка 3 500 тенге в магазине канцтоваров».","Задание: для каждого: мошенничество или нет, признаки, правильное действие."],"hand":"Сдать: таблицу","answers":[["","1–4 — мошенничество; 5 — обычное уведомление, но если покупку не делал — звонить в банк по номеру на карте"]]},{"n":"2","title":"Шаблон питча «Что? Кому? Как?»","lines":["Что: схема и её признаки (30 секунд). Кому: кто чаще попадается (15 секунд). Как: сценка правильного ответа (60 секунд). Слоган (15 секунд)."],"hand":"Сдать: выступление.","answers":[]},{"n":"3","title":"Олимпиадные задачи ФГиБ","lines":["Задача 1. «Клуб» обещает 25% в месяц. Банк платит по вкладу около 12% в год. Во сколько раз обещание «клуба» за год (простой процент) выше?","Задача 2. В пирамиду вступили 10 человек по 50 000 условных тенге. Организатор обещает каждому 25% в месяц. Сколько нужно выплатить за первый месяц и на сколько месяцев хватит взносов, если новых участников нет и организатор ничего не забирает себе?"],"hand":"Сдать: решения.","answers":[["","25% × 12 = 300% в год; 300 ÷ 12 = в 25 раз — явный признак пирамиды."],["","10 × 12 500 = 125 000 в месяц; 500 000 ÷ 125 000 = 4 месяца, затем выплаты прекратятся."]]}],"practice":[{"type":"case","title":"SMS от «банка»","minutes":9,"source":"Условная ситуация по типичной схеме мошенников","hook":"«Ваша карта заблокирована. Перезвоните или назовите код из SMS».","story":["Маме Алии звонят с незнакомого номера: «Служба безопасности банка. С вашей карты пытаются украсть деньги».","Голос уверенный, называет имя мамы и последние цифры карты.","«Чтобы отменить операцию, назовите код, который придёт сейчас в SMS»."],"question":"Что нужно сделать?","options":["Перезвонить на этот же номер","Назвать код — ведь знают имя","Положить трубку и самой позвонить в банк по номеру с карты","Перевести деньги на «безопасный счёт»"],"answerIndex":2,"reveal":"Банк никогда не просит код из SMS, PIN или CVV. Мошенники могут знать имя и часть номера карты. Правило: положить трубку и позвонить в банк самому по официальному номеру.","teams":"Команды: составьте «памятку для бабушки» из 5 правил против телефонных мошенников.","takeaway":"Код из SMS не называют никому — даже «банку»."},{"type":"case","title":"Самая большая пирамида","minutes":8,"source":"Бернард Мейдофф, США, раскрыта в декабре 2008","hook":"Уважаемый финансист, бывший глава биржи NASDAQ. Что могло пойти не так?","story":["Бернард Мейдофф десятилетиями управлял деньгами богатых людей и фондов.","Он показывал стабильную прибыль каждый год — даже когда рынок падал.","В 2008 году, во время кризиса, клиенты захотели забрать деньги."],"question":"Что, по-вашему, должно было насторожить клиентов?","options":["Слишком стабильная прибыль, даже когда все теряли","Высокие налоги","Ничего не могло","Его известность"],"answerIndex":0,"reveal":"Мейдофф платил старым клиентам деньгами новых — это была крупнейшая пирамида в истории. Его приговорили к 150 годам тюрьмы. Подозрительно ровная прибыль без убытков — тревожный знак.","teams":"Команды: оцените 3 «инвестиции» по шкале риска и найдите тревожные признаки.","takeaway":"Слишком хорошо, чтобы быть правдой, — значит неправда."}],"homework":"Сделать для семейного чата короткую памятку из 5 вопросов «детектора сообщения» и отправить её родным (по согласию родителей).","support":"Лист разбора с подсказками-галочками по 5 вопросам детектора; готовые фразы отказа: «Я перезвоню в банк сам», «Позвоню тебе голосом».","advanced":"Придумать шестое сообщение-ловушку, где признаки спрятаны хорошо, и объяснить, по каким деталям его всё равно можно распознать.","photo":{"src":"lessons/img/08_26.jpg","author":"Hassan OUAJBIR","q":["Что вы видите на фото? Как это связано с нашей темой?","Какой признак пирамиды можно было заметить заранее?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g08-l26.pptx","name":"26. Как защитить себя от фин. мошенников — практикум (8 кл).pptx","mb":1.4}},{"id":"08_27","g":8,"l":27,"topic":"Практическое занятие. Составление личного и семейного бюджета","module":"Бюджетирование (личные финансы)","format":"Проектная мастерская","skills":["Финансовое мышление","Командная работа","Креативность"],"goal":"К концу урока ученик сможет составить личный бюджет условного подростка на месяц в таблице: доходы, обязательные и желательные расходы, сбережения, и проверить, что расходы с накоплениями не превышают доходы.","criteria":["Я заношу все доходы и расходы в нужные строки таблицы.","Я делю расходы на обязательные и желательные и закладываю сбережения.","Я проверяю баланс (доходы − расходы − сбережения ≥","и объясняю, что изменить, если он отрицательный."],"result":"Командный шаблон таблицы личного бюджета и заполненный личный бюджет условного подростка на месяц (персонаж из карточки) с выводом о балансе.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Бюджет (budget)","real":"План доходов и расходов на период, например на месяц","shown":"План доходов и расходов на период, например на месяц","truth":true,"first":"Б"},{"term":"Личный бюджет","real":"Бюджет одного человека; он часть семейного бюджета","shown":"Разница между доходами и расходами вместе со сбережениями","truth":false,"first":"Л"},{"term":"Семейный бюджет","real":"Общий план доходов и расходов всей семьи","shown":"Общий план доходов и расходов всей семьи","truth":true,"first":"С"},{"term":"Обязательные расходы","real":"Траты, без которых не обойтись: проезд, связь, школьные принадлежности","shown":"Бюджет одного человека; он часть семейного бюджета","truth":false,"first":"О"},{"term":"Желательные расходы","real":"Траты «хочу»: развлечения, сладости, подписки","shown":"Траты «хочу»: развлечения, сладости, подписки","truth":true,"first":"Ж"},{"term":"Баланс бюджета","real":"Разница между доходами и расходами вместе со сбережениями","shown":"Траты, без которых не обойтись: проезд, связь, школьные принадлежности","truth":false,"first":"Б"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Бюджет (budget)","def":"План доходов и расходов на период, например на месяц"},{"term":"Личный бюджет","def":"Бюджет одного человека; он часть семейного бюджета"},{"term":"Семейный бюджет","def":"Общий план доходов и расходов всей семьи"},{"term":"Обязательные расходы","def":"Траты, без которых не обойтись: проезд, связь, школьные принадлежности"},{"term":"Желательные расходы","def":"Траты «хочу»: развлечения, сладости, подписки"},{"term":"Баланс бюджета","def":"Разница между доходами и расходами вместе со сбережениями"},{"term":"Правило 50/30/20","def":"Ориентир: 50% дохода на обязательное, 30% на желательное, 20% на сбережения"}],"english":"budget — бюджет; money — деньги","concepts":{"head":"Понятия","items":["Бюджет (budget) — это план, а не отчёт: он составляется до того, как потрачены деньги (money).","Личный бюджет подростка — часть семейного: что-то оплачивают родители, а какими-то деньгами подросток распоряжается сам."]},"steps":{"head":"Как составить, по шагам","items":["Записать все доходы месяца (карманные, подарки, подработка)","Записать обязательные расходы","Записать желательные расходы","Заложить сбережения — лучше сразу, «заплати сначала себе»","Посчитать баланс: доходы − расходы − сбережения","Если баланс отрицательный — сократить желательные расходы, а не сбережения; ж) сверить с правилом 50/30/20 как ориентиром"]},"scheme":"Таблица «Статья — План — Тип (обяз./желат./сбереж.)», внизу строки «Итого доходы», «Итого расходы», «Сбережения», «Баланс»; рядом круговая диаграмма 50/30/20.","examples":[{"lab":"Казахстанский","text":"Казахстанский (условный персонаж): Медина из Астаны, условный доход 30 000 тенге в месяц. Обязательные: проезд 6 000, мобильная связь 3 000, канцтовары 2 000 — всего 11 000. Желательные: кино 4 000, кафе с друзьями 6 000, подписка на музыку 1 500 — всего 11 500. Сбережения 6 000 (20%). Баланс: 30 000 − 11 000 − 11 500 − 6 000 = 1 500 — бюджет сбалансирован."},{"lab":"Мировой","text":"Правило 50/30/20 широко известно по всему миру как простой ориентир для личного бюджета."}],"mistake":{"myth":"Ученики забывают мелкие ежедневные траты (перекусы, проезд), и бюджет «не сходится»","fix":"Умножьте ежедневную трату на число учебных дней — например, 300 × 20 = 6 000."},"check":[{"q":"Подписка на онлайн-кино — обязательный расход?","a":"Нет, желательный"},{"q":"Что сокращать, если баланс в минусе?","a":"Желательные расходы"},{"q":"Почему сбережения лучше закладывать в начале месяца?","a":"Иначе к концу месяца на них ничего не останется"}],"kz":{"text":"Halyk Bank и финансовые приложения. Крупнейший казахстанский банк Halyk Bank, как и другие банки страны, показывает клиентам в мобильном приложении расходы по категориям.","link":"такая аналитика помогает сравнить план бюджета и факт."},"world":{"text":"Международная организация ОЭСР в программе PISA проверяет финансовую грамотность 15-летних школьников разных стран, в том числе умение планировать бюджет.","link":""},"fact":"Правило 50/30/20 популяризировали американский профессор права Элизабет Уоррен и её дочь Амелия Уоррен Тьяги в книге «All Your Worth» (2005); с тех пор его используют как простой ориентир для личного бюджета во многих странах.","cards":[{"n":"1","title":"Персонажи (условные доходы и расходы)","lines":["Персонаж А. Тимур, 14 лет, Караганда. Доход: 25 000.","Траты: проезд 5 000, связь 2 500, перекусы 300 в день × 20 дней, компьютерный клуб 5 000, подарок другу 3 000.","Персонаж Б. Айым, 15 лет, Алматы. Доход: 35 000 (карманные 25 000 + подработка 10 000).","Траты: проезд 7 000, связь 3 000, курсы рисования 8 000, кино 4 000, одежда 10 000.","Задание: внесите данные в шаблон, разделите расходы на обязательные и желательные, заложите сбережения 10–20%, посчитайте баланс и предложите изменения, если баланс отрицательный."],"hand":"Сдать: таблицу (подсказка: Тимур — расходы 21 500, при сбережениях 2 500 баланс 1 000; Айым — расходы 32 000, при сбережениях 3 500 баланс −500, нужно сократить желательные траты).","answers":[]},{"n":"2","title":"Олимпиадные задачи ФГиБ","lines":["Задача 1. Доход подростка 40 000 условных тенге. Сколько по правилу 50/30/20 приходится на обязательные расходы, желательные и сбережения?","Задача 2. Ученик тратит 400 условных тенге в день на перекусы 22 учебных дня в месяц. Сколько он сэкономит за учебный год (9 месяцев), если сократит траты вдвое?"],"hand":"Сдать: решения.","answers":[["","20 000, 12 000, 8 000."],["","200 × 22 × 9 = 39 600."]]},{"n":"3","title":"Открытка из будущего","lines":["Задание: «Через три месяца я накопил на цель, потому что каждый месяц … Действие на 48 часов: …»"],"hand":"Сдать: вслух только действие.","answers":[]}],"practice":[{"type":"case","title":"Первая стипендия Дианы","minutes":9,"source":"Условная ситуация","hook":"Студентка получает 50 000 тенге стипендии. Хватит ли до конца месяца?","story":["Диана поступила в колледж и получает стипендию 50 000 тенге.","Проезд — 8 000, обеды — 20 000, телефон — 3 000, канцтовары — 4 000.","Ещё она хочет накопить на наушники за 30 000 тенге."],"question":"Сколько Диана может откладывать в месяц после обязательных расходов?","options":["Ничего","До 15 000 тенге","35 000 тенге","50 000 тенге"],"answerIndex":1,"reveal":"50 000 − (8 000 + 20 000 + 3 000 + 4 000) = 15 000 тенге. Если откладывать всё, на наушники хватит за 2 месяца. Но разумно оставить немного на непредвиденное.","teams":"Команды: составьте личный бюджет Дианы на месяц с накоплением и запасом.","takeaway":"Личный бюджет: обязательное → накопления → остальное."},{"type":"case","title":"Семейный бюджет Сериковых","minutes":8,"source":"Условная ситуация","hook":"Доход 700 000 тенге. Расходы растут. Где семья теряет деньги?","story":["Семья из 4 человек: доход 700 000 тенге.","Еда 220 000, коммуналка 60 000, кредит за машину 120 000, транспорт 50 000, одежда 60 000, подписки и доставка еды 90 000, кружки детей 70 000.","В конце месяца денег не остаётся совсем."],"question":"Какая статья больше всего похожа на «утечку» денег?","options":["Подписки и доставка еды — 90 000","Еда","Коммуналка","Кружки детей"],"answerIndex":0,"reveal":"Сумма расходов: 670 000, остаётся 30 000. Подписки и доставка — гибкая статья, её можно сократить. Если сократить вдвое, появятся 45 000 на подушку безопасности.","teams":"Команды: перестройте бюджет Сериковых так, чтобы каждый месяц откладывать 10% дохода.","takeaway":"Сначала ищем гибкие статьи — там прячутся утечки."}],"homework":"Составить свой личный бюджет на следующую неделю в шаблоне команды (суммы можно условные) и через неделю сравнить план и факт.","support":"Шаблон с уже названными статьями и подсказками-примерами; калькулятор; пример Медины на столе.","advanced":"Сравнить бюджет персонажа с правилом 50/30/20 в процентах и предложить 2 изменения, чтобы приблизиться к нему.","photo":{"src":"lessons/img/08_27.jpg","author":"Eric Rothermel","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему умение составить бюджет считается важным навыком для жизни во всём мире?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g08-l27.pptx","name":"27. Практическое занятие. Составление личного и семейного бюджета (8 кл).pptx","mb":1.4}},{"id":"08_28","g":8,"l":28,"topic":"После ярмарки: считаем прибыль","module":"Бюджетирование (личные финансы)","format":"Симуляция, ярмарка","skills":["Финансовое мышление","Работа с клиентом"],"goal":"К концу урока ученик сможет разобрать итоги ярмарки на цифрах: посчитать выручку, расходы, прибыль и прибыль на единицу товара по каждому товару, сравнить план и факт и проверить одно ценовое решение на повторной мини-ярмарке.","criteria":["Я правильно считаю выручку, расходы, прибыль и прибыль на единицу по каждому товару.","Я сравниваю план и факт и объясняю отклонения наблюдениями о покупателях.","Я предлагаю и проверяю одно решение (цена, ассортимент, выкладка) и оцениваю его результат."],"result":"Расчёт выручки и прибыли команды (план — факт, по товарам) и лист «Что сработало / что улучшить» с результатом проверки ценового решения.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Ярмарка (fair)","real":"Ивент, где команды продают товары покупателям","shown":"Ивент, где команды продают товары покупателям","truth":true,"first":"Я"},{"term":"Выручка","real":"Все деньги (money) от продаж: цена × количество","shown":"Разница между планом и фактом","truth":false,"first":"В"},{"term":"Прибыль (profit)","real":"Выручка минус расходы","shown":"Выручка минус расходы","truth":true,"first":"П"},{"term":"Прибыль на единицу","real":"Цена минус себестоимость одной штуки","shown":"Все деньги (money) от продаж: цена × количество","truth":false,"first":"П"},{"term":"Рентабельность","real":"Какую долю выручки составляет прибыль, в процентах","shown":"Какую долю выручки составляет прибыль, в процентах","truth":true,"first":"Р"},{"term":"Отклонение","real":"Разница между планом и фактом","shown":"Цена минус себестоимость одной штуки","truth":false,"first":"О"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Ярмарка (fair)","def":"Ивент, где команды продают товары покупателям"},{"term":"Выручка","def":"Все деньги (money) от продаж: цена × количество"},{"term":"Прибыль (profit)","def":"Выручка минус расходы"},{"term":"Прибыль на единицу","def":"Цена минус себестоимость одной штуки"},{"term":"Рентабельность","def":"Какую долю выручки составляет прибыль, в процентах"},{"term":"Отклонение","def":"Разница между планом и фактом"},{"term":"Непроданный остаток","def":"Товар, который закупили, но не продали; его стоимость уже входит в расходы"}],"english":"fair — ярмарка; profit — прибыль; money — деньги","concepts":{"head":"Понятия","items":["Прибыль (profit) = выручка − расходы.","Прибыль на единицу = цена − себестоимость.","Рентабельность = прибыль ÷ выручка × 100%.","Важно: непроданный товар — это расходы без выручки, он снижает прибыль."]},"steps":{"head":"Как считаем, по шагам","items":["По каждому товару: закуплено, продано, цена, себестоимость","Выручка = цена × продано","Расходы = себестоимость × закуплено + оформление","Прибыль и рентабельность","Сравнение с планом","Причины отклонений по наблюдениям: цена, выкладка, общение с покупателем; ж) решение для проверки"]},"scheme":"Таблица «Товар — Закуплено — Продано — Цена — Себестоимость — Выручка — Расходы — Прибыль», под ней «План / Факт / Отклонение» и колонки «Сработало / Улучшить».","examples":[{"lab":"Казахстанский","text":"Команда 8 класса в Павлодаре продавала брелоки (себестоимость 200, цена 500) и открытки (себестоимость 300, цена 400). Закупили по 20 штук, оформление 600. Продали 18 брелоков и 7 открыток. Выручка: 9 000 + 2 800 = 11 800. Расходы: 4 000 + 6 000 + 600 = 10 600. Прибыль 1 200, рентабельность ≈ 10%. Вывод: открытки «съели» прибыль — 13 штук остались; решение: закупать меньше открыток или поднять ценность (подписать открытки на заказ)."},{"lab":"Мировой","text":"Розничные сети анализируют продажи по каждому товару и убирают с полок то, что не продаётся."}],"mistake":{"myth":"Расходы считают только по проданным товарам","fix":"Покажите, что деньги за непроданные 13 открыток уже потрачены."},"check":[{"q":"Почему при хорошей выручке может быть маленькая прибыль?","a":"Большие расходы или непроданный остаток"},{"q":"Какой товар выгоднее: с прибылью 300 на единицу или 100?","a":"С 300, если его покупают в похожем количестве"},{"q":"Как проверить решение?","a":"Применить на мини-ярмарке и сравнить цифры"}],"kz":{"text":"Кондитерская фабрика «Баян Сулу» (Костанай). Одна из крупнейших кондитерских компаний Казахстана выпускает множество видов конфет и печенья и, как любой производитель, следит, какие товары приносят прибыль, а какие нет.","link":"решения об ассортименте принимаются по цифрам продаж."},"world":{"text":"Компания Zara (Inditex, Испания) известна тем, что быстро анализирует продажи каждого товара и за несколько недель меняет ассортимент: то, что не продаётся, снимают, а популярное допроизводят.","link":""},"fact":"Компания Zara принадлежит испанской группе Inditex, основанной Амансио Ортегой; модель быстрого обновления ассортимента по данным продаж сделала её одной из крупнейших в мире компаний по продаже одежды.","cards":[{"n":"1","title":"Итоги ярмарки по товарам","lines":["Учебные данные: брелоки — закуплено 20, себестоимость 200, цена 500, продано 18; открытки — закуплено 20, себестоимость 300, цена 400, продано 7; оформление 600. План: выручка 14 000, прибыль 3 400.","Задание: посчитайте выручку, расходы, прибыль, рентабельность и отклонение от плана; найдите товар, который снизил прибыль; заполните такую же таблицу для своей команды."],"hand":"Сдать: таблицу","answers":[["","Выручка 11 800, расходы 10 600, прибыль 1 200, рентабельность ≈ 10%, отклонение прибыли −2 200"]]},{"n":"2","title":"События мини-ярмарки","lines":["1) Покупатель готов взять 5 открыток, если цена 300. 2) Конкурент предлагает похожие брелоки по 450. 3) Покупатель просит подписать открытку на заказ. 4) Пришла группа покупателей с ограниченным бюджетом 1 000 на человека.","Задание: примите решение и запишите, как оно влияет на прибыль."],"hand":"Сдать: записи с учётом.","answers":[]},{"n":"3","title":"Олимпиадные задачи ФГиБ","lines":["Задача 1. Команда закупила 30 кружек по 600 условных тенге и продала 24 по 1 000. Найдите прибыль и рентабельность.","Задача 2. Что выгоднее: продать 20 закладок по 250 (себестоимость 100) или 30 закладок по 200 при той же себестоимости?"],"hand":"Сдать: решения.","answers":[["","Выручка 24 000, расходы 18 000, прибыль 6 000, рентабельность 25%."],["","Прибыль 20 × 150 = 3 000 против 30 × 100 = 3 000 — одинаково, но первый вариант требует меньше товара и труда."]]}],"practice":[{"type":"case","title":"Девять стаканов в день","minutes":9,"source":"Первый год продаж Coca-Cola, Атланта, 1886","hook":"Самый известный напиток мира в первый год продавался… очень плохо.","story":["Фармацевт Джон Пембертон в 1886 году придумал напиток и продавал его в аптеке в Атланте.","В первый год продавали в среднем около 9 стаканов в день.","На рекламу и производство Пембертон потратил больше, чем заработал."],"question":"Какой был финансовый результат первого года?","options":["Огромная прибыль","Ровно ноль","Убыток: расходы больше выручки","Нельзя узнать"],"answerIndex":2,"reveal":"В первый год Coca-Cola принесла убыток. Выручка — это ещё не прибыль: нужно вычесть все расходы. Прибыль появилась позже, когда продажи выросли.","teams":"Команды: посчитайте прибыль своей команды: выручка − материалы − упаковка − реклама.","takeaway":"Прибыль = выручка − все расходы."},{"type":"case","title":"Выручка большая, а прибыли нет","minutes":8,"source":"Условная ситуация","hook":"Команда продала больше всех, но почему-то заработала меньше всех.","story":["Команда А продала 60 сэндвичей по 500 тенге. Команда Б — 30 браслетов по 700 тенге.","Расходы А: продукты 20 000, упаковка 4 000, реклама 2 000.","Расходы Б: бусины 6 000, нитки 1 000."],"question":"Чья прибыль больше?","options":["Команды Б: 14 000 против 4 000","Ни у кого нет прибыли","Одинаковая","Команды А: у неё больше выручка"],"answerIndex":0,"reveal":"А: 30 000 − 26 000 = 4 000. Б: 21 000 − 7 000 = 14 000. Большая выручка не гарантирует большую прибыль, если расходы высокие.","teams":"Команды: посчитайте рентабельность: прибыль ÷ выручка × 100% для обеих команд и своей.","takeaway":"Считаем не выручку, а прибыль и рентабельность."}],"homework":"Подготовить «финансовый отчёт команды» на полстраницы: выручка, расходы, прибыль, рентабельность, лучший и худший товар и 2 решения на следующую ярмарку.","support":"Таблица с формулами в заголовках колонок и посчитанной первой строкой; помощь пары-«финансиста».","advanced":"Посчитать, при какой цене открыток команда из примера вышла бы на рентабельность 20% при тех же продажах.","photo":{"src":"lessons/img/08_28.jpg","author":"Alexander Mils","q":["Что вы видите на фото? Как это связано с нашей темой?","Как идею «анализа по каждому товару» применить к нашему прилавку?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g08-l28.pptx","name":"28. После ярмарки — считаем прибыль (8 кл).pptx","mb":1.5}},{"id":"08_29","g":8,"l":29,"topic":"Практическое занятие. Составление личного и семейного бюджета: практикум","module":"Бюджетирование (личные финансы)","format":"Проектная мастерская","skills":["Финансовое мышление","Командная работа","Креативность"],"goal":"К концу урока команда сможет составить семейный бюджет условной семьи на месяц в таблице, найти не менее 3 статей, где можно сэкономить, и рассчитать, сколько семья сбережёт за месяц и за год.","criteria":["Я правильно заполняю таблицу семейного бюджета и считаю баланс.","Я нахожу 3 реальные меры экономии без ущерба для обязательных нужд и считаю эффект в условных тенге.","Я вместе с командой предлагаю, куда направить сэкономленные деньги, и объясняю почему."],"result":"Командный проект «Бюджет семьи на месяц»: таблица доходов и расходов условной семьи, 3 меры экономии с расчётом и план, куда направить сэкономленное.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Бюджет (budget)","real":"План доходов и расходов на период","shown":"План доходов и расходов на период","truth":true,"first":"Б"},{"term":"Семейный бюджет","real":"Общий план доходов и расходов всех членов семьи","shown":"Ситуация, когда расходы больше доходов","truth":false,"first":"С"},{"term":"Постоянные расходы","real":"Суммы, которые почти не меняются каждый месяц: коммунальные услуги, связь, кредит","shown":"Суммы, которые почти не меняются каждый месяц: коммунальные услуги, связь, кредит","truth":true,"first":"П"},{"term":"Переменные расходы","real":"Суммы, которые можно менять: продукты, развлечения, такси","shown":"Общий план доходов и расходов всех членов семьи","truth":false,"first":"П"},{"term":"Экономия","real":"Сокращение расходов без потери важного","shown":"Сокращение расходов без потери важного","truth":true,"first":"Э"},{"term":"Дефицит бюджета","real":"Ситуация, когда расходы больше доходов","shown":"Суммы, которые можно менять: продукты, развлечения, такси","truth":false,"first":"Д"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Бюджет (budget)","def":"План доходов и расходов на период"},{"term":"Семейный бюджет","def":"Общий план доходов и расходов всех членов семьи"},{"term":"Постоянные расходы","def":"Суммы, которые почти не меняются каждый месяц: коммунальные услуги, связь, кредит"},{"term":"Переменные расходы","def":"Суммы, которые можно менять: продукты, развлечения, такси"},{"term":"Экономия","def":"Сокращение расходов без потери важного"},{"term":"Дефицит бюджета","def":"Ситуация, когда расходы больше доходов"},{"term":"Профицит бюджета","def":"Ситуация, когда доходы больше расходов, остаются свободные деньги"}],"english":"budget — бюджет; money — деньги; practice — практика","concepts":{"head":"Понятия","items":["Семейный бюджет (budget) — это доходы всех взрослых (зарплата, пенсия, пособия) и расходы на всю семью.","Расходы делятся на постоянные и переменные.","Если расходы больше доходов — дефицит, меньше — профицит.","Экономить проще всего на переменных расходах."]},"steps":{"head":"Как составить и найти экономию, по шагам","items":["Записать все доходы","Записать постоянные расходы","Записать переменные расходы","Посчитать баланс","По каждой переменной статье спросить: «Можно ли дешевле без потери важного?»","Посчитать эффект каждой меры за месяц и за год; ж) решить, куда направить деньги (money): резерв, цель семьи, погашение долга"]},"scheme":"Таблица «Статья — Тип (пост./перем.) — Сумма — Мера экономии — Эффект в месяц — Эффект в год»; внизу «Доходы — Расходы = Баланс» и стрелка «Сэкономленное → Резерв / Цель».","examples":[{"lab":"Казахстанский","text":"Казахстанский (условная семья): семья Нуржановых из Костаная, доход 420 000 условных тенге. Постоянные: коммунальные 45 000, связь и интернет 12 000, кредит 60 000. Переменные: продукты 160 000, проезд и такси 40 000, кафе и доставка еды 35 000, развлечения 25 000, одежда 30 000. Всего расходов 407 000, профицит 13 000. Меры экономии: готовить дома вместо доставки (−20 000), такси заменить автобусом 2 раза в неделю (−8 000), покупать продукты по списку (−12 000). Итого экономия 40 000 в месяц, 480 000 в год."},{"lab":"Мировой","text":"Во многих странах семьи используют метод «конвертов» — заранее раскладывают деньги на категории расходов."}],"mistake":{"myth":"«экономия» за счёт обязательного (отказаться от еды, лекарств, проезда в школу)","fix":"Правило «экономим на желаниях и привычках, а не на базовых нуждах»."},"check":[{"q":"Можно ли сэкономить на коммунальных услугах?","a":"Немного: выключать свет, экономить воду, но это постоянная статья"},{"q":"Почему экономию считают за год?","a":"Так видно реальный эффект"},{"q":"Что делать с дефицитом?","a":"Сокращать переменные расходы, искать доп. доход, не брать новые долги"}],"kz":{"text":"Magnum Cash & Carry и другие продуктовые сети Казахстана. Крупнейшая казахстанская продуктовая сеть Magnum и другие сети страны проводят акции и программы лояльности, которые помогают семьям экономить на продуктах.","link":"разумные покупки по списку и использование акций — реальные меры экономии в семейном бюджете."},"world":{"text":"ЦУР ООН № 12 «Ответственное потребление» связана с семейным бюджетом: меньше выброшенной еды и импульсивных покупок — это и экономия денег, и забота о планете. По оценкам ООН, в мире выбрасывается значительная часть произведённой еды.","link":""},"fact":"Метод «конвертов» для бюджета пришёл из времён, когда зарплату выдавали наличными: деньги сразу раскладывали по конвертам «аренда», «еда», «одежда», и когда конверт пустел, траты в этой категории прекращались. Сегодня банки и приложения повторяют эту идею в виде цифровых «копилок» и категорий.","cards":[{"n":"1","title":"Условные семьи","lines":["Семья А (3 человека). Доход 380 000. Постоянные: коммунальные 40 000, интернет и связь 15 000, кредит 50 000. Переменные: продукты 150 000, такси 35 000, доставка еды 30 000, развлечения 30 000, одежда 40 000.","Семья Б (5 человек). Доход 500 000. Постоянные: коммунальные 55 000, связь 18 000, аренда 120 000. Переменные: продукты 200 000, проезд 30 000, кружки детей 40 000, развлечения 20 000, одежда 35 000.","Задание: заполните таблицу, посчитайте баланс, предложите 3 меры экономии с эффектом за месяц и год, решите, куда направить сэкономленное."],"hand":"Сдать: таблицу (подсказка: А — расходы 390 000, дефицит −10 000; Б — расходы 518 000, дефицит −18 000).","answers":[]},{"n":"2","title":"Олимпиадные задачи ФГиБ","lines":["Задача 1. Семья тратит на доставку еды 32 000 условных тенге в месяц. Если готовить дома, продукты для тех же блюд стоят 12 000. Сколько семья сэкономит за год?","Ответ: (32 000 − 12 000) × 12 = 240 000.","Задача 2. Расходы семьи 450 000 в месяц, из них переменные 270 000. Семья сократила переменные расходы на 10%. На сколько процентов уменьшились общие расходы?"],"hand":"Сдать: решения.","answers":[["","27 000 ÷ 450 000 × 100% = 6%."]]},{"n":"3","title":"Открытка из будущего","lines":["Задание: «Через три месяца наша семья сэкономила, потому что я … Действие на 48 часов: …»"],"hand":"Сдать: вслух только действие.","answers":[]}],"practice":[{"type":"case","title":"Финансовый план на год","minutes":9,"source":"Условная ситуация","hook":"Подросток хочет к лету ноутбук за 240 000 тенге. Реально?","story":["Темирлан получает 15 000 тенге в месяц карманных денег и иногда подрабатывает (примерно 10 000 в месяц).","На обеды и проезд уходит 12 000 в месяц.","До лета 8 месяцев, ноутбук стоит 240 000 тенге."],"question":"Хватит ли денег к лету, если откладывать всё свободное?","options":["Да, ровно","Да, с запасом","Невозможно посчитать","Нет: 13 000 × 8 = 104 000, нужно больше времени или доход"],"answerIndex":3,"reveal":"Свободно: 25 000 − 12 000 = 13 000 в месяц, за 8 месяцев — 104 000. Не хватает 136 000. Варианты: копить дольше (около 19 месяцев), найти больше подработки, выбрать ноутбук дешевле.","teams":"Команды: составьте план, при котором Темирлан купит ноутбук за 12 месяцев. Что изменить?","takeaway":"План показывает правду: реальна ли цель и что изменить."},{"type":"case","title":"Две семьи — один доход","minutes":8,"source":"Условная ситуация","hook":"Одинаковые зарплаты, разные результаты через год.","story":["Две семьи получают по 500 000 тенге.","Семья А сначала тратит, а что осталось — откладывает. Обычно не остаётся ничего.","Семья Б в день зарплаты сразу переводит 50 000 на накопительный счёт, а живёт на остальное."],"question":"Сколько накопит семья Б за год?","options":["6 000 000 тенге","0 тенге","600 000 тенге","50 000 тенге"],"answerIndex":2,"reveal":"50 000 × 12 = 600 000 тенге — и это без процентов. Правило «сначала заплати себе» работает, потому что откладывание происходит до трат, а не после.","teams":"Команды: составьте семейный бюджет по правилу «сначала заплати себе» и 50/30/20.","takeaway":"Сначала заплати себе — потом трать."}],"homework":"Предложить дома одну меру экономии, которую может выполнить сам ученик (например, выключать свет, не покупать воду в бутылках), и посчитать её примерный эффект за месяц в условных тенге.","support":"Таблица с готовыми статьями и подсказка «список возможных мер экономии»; калькулятор.","advanced":"Рассчитать, какой процент расходов семьи составляет экономия, и за сколько месяцев семья соберёт резерв на 3 месяца постоянных расходов только за счёт сэкономленного.","photo":{"src":"lessons/img/08_29.jpg","author":"Eric Rothermel","q":["Что вы видите на фото? Как это связано с нашей темой?","Какая мера экономии в нашем бюджете одновременно полезна для экологии?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g08-l29.pptx","name":"29. Практическое занятие. Составление личного и семейного бюджета — практикум (8 кл).pptx","mb":1.4}},{"id":"08_30","g":8,"l":30,"topic":"Итоговая работа за полугодие (Тестирование по пройденному модулю)","module":"Бюджетирование (личные финансы)","format":"Итоговая работа","skills":["Финансовое мышление","Критическое мышление"],"goal":"К концу урока ученик сможет выполнить итоговую работу по модулю «Бюджетирование (личные финансы)»: правильно ответить не менее чем на 8 из 12 вопросов теста по терминам и решить практическое задание по бюджету, сбережениям и защите от мошенничества.","criteria":["Я выполняю задания по темам модуля: карты, сбережения, депозит и инвестиции, страхование, бюджет, мошенничество.","Я объясняю свои решения и расчёты.","Я оцениваю свой результат по чек-листу самопроверки."],"result":"Итоговая работа: тест из 12 вопросов по терминам модуля и практическое задание «Финансовый план условного подростка» (бюджет, план сбережений, расчёт процентов, распознавание мошенничества).","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Тестирование (testing)","real":"Проверка знаний с помощью заданий с ответами","shown":"Проверка знаний с помощью заданий с ответами","truth":true,"first":"Т"},{"term":"Повторение (review)","real":"Возвращение к изученному перед проверкой","shown":"Запас на 3–6 месяцев обязательных расходов","truth":false,"first":"П"},{"term":"Бюджет","real":"План доходов и расходов на период","shown":"План доходов и расходов на период","truth":true,"first":"Б"},{"term":"Депозит","real":"Вклад в банке под проценты; сложный процент — проценты на проценты","shown":"Возвращение к изученному перед проверкой","truth":false,"first":"Д"},{"term":"Страховой полис","real":"Договор страхования; франшиза — часть ущерба, которую платит сам клиент","shown":"Договор страхования; франшиза — часть ущерба, которую платит сам клиент","truth":true,"first":"С"},{"term":"Подушка безопасности","real":"Запас на 3–6 месяцев обязательных расходов","shown":"Вклад в банке под проценты; сложный процент — проценты на проценты","truth":false,"first":"П"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Тестирование (testing)","def":"Проверка знаний с помощью заданий с ответами"},{"term":"Повторение (review)","def":"Возвращение к изученному перед проверкой"},{"term":"Бюджет","def":"План доходов и расходов на период"},{"term":"Депозит","def":"Вклад в банке под проценты; сложный процент — проценты на проценты"},{"term":"Страховой полис","def":"Договор страхования; франшиза — часть ущерба, которую платит сам клиент"},{"term":"Подушка безопасности","def":"Запас на 3–6 месяцев обязательных расходов"},{"term":"Финансовая пирамида","def":"Схема, где доход старым участникам платят деньгами (money) новых"}],"english":"testing — тестирование; money — деньги; review — повторение","concepts":{"head":"Базовые понятия модуля","items":["доходы и расходы, личный и семейный бюджет, правило 50/30/20, дебетовая, накопительная и кредитная карта, льготный период, сбережения и план сбережений, активный и пассивный доход, депозит, инвестиции, акция, облигация, простой и сложный процент, подушка безопасности, страхование, полис, франшиза, мошенничество, фишинг, финансовая пирамида, прибыль и резерв."]},"steps":{"head":"Как выполнять работу, по шагам","items":["Прочитать все задания","Тест — 12 минут","Практическое задание — 15 минут","1 минута на проверку расчётов"]},"scheme":"«Деньги под контролем»: Доход → Бюджет (50/30/20) → Подушка → Цели (депозит) → Инвестиции; сбоку «Щит»: страховка и правила безопасности.","examples":[{"lab":"Казахстанский","text":"Взнос = (цель − есть) ÷ месяцы, например (90 000 − 18 000) ÷ 8 = 9 000 условных тенге. Сложный процент: 100 000 × 1,1 × 1,1 = 121 000."},{"lab":"Мировой","text":"Схема Понци 1920 года — эталон пирамиды."}],"mistake":{"myth":"Путают простой и сложный процент и забывают вычесть уже накопленное в плане сбережений","fix":"Разбор в чек-листе самопроверки. Оценивание: тест 12 баллов, практика 8 баллов, сумма 20 переводится в балл 1–10 (20 ÷ 2) и идёт в 30% индекса «Лидер бизнеса»."},"check":[{"q":"Банк может попросить SMS-код по телефону?","a":"Нет"},{"q":"Выплата при ущербе 50 000 и франшизе 10 000?","a":"40 000"},{"q":"Что сначала — подушка или акции?","a":"Подушка"}],"kz":{"text":"Казахстанская фондовая биржа (KASE) и «Народное IPO». В 2012 и 2014 годах казахстанцы покупали акции «КазТрансОйл» и KEGOC через биржу — пример того, как знания модуля (инвестиции, риск, доходность) нужны обычным гражданам. Используйте в начале урока как мотивацию: «Эти знания нужны взрослым каждый день».","link":""},"world":{"text":"Международная программа PISA (ОЭСР) проверяет финансовую грамотность 15-летних школьников разных стран: умение планировать бюджет, понимать проценты и распознавать финансовые риски.","link":""},"fact":"Первые монеты в истории начали чеканить в Лидии (на территории современной Турции) примерно в VII веке до н. э.; до этого люди обменивались товарами или слитками металла.","cards":[{"n":"1","title":"Тест (12 вопросов, по 1 баллу)","lines":["1) Дебетовая карта: а) деньги банка в долг; б) свои деньги на счёте; в) страховка.","2) Льготный период — время, когда: а) по кредитной карте не начисляются проценты; б) банк закрыт; в) нельзя платить картой.","3) Пассивный доход: а) подработка; б) проценты по вкладу; в) зарплата.","4) Взнос в плане сбережений = а) цель × месяцы; б) (цель − уже есть) ÷ месяцы; в) цель − месяцы.","5) Подушка безопасности обычно равна: а) 1 неделе расходов; б) 3–6 месяцам обязательных расходов; в) годовому доходу.","6) Облигация — это: а) доля в компании; б) долговая бумага с процентом; в) кредитная карта.","7) Сложный процент: а) проценты начисляются и на проценты; б) проценты не начисляются; в) проценты только за первый год.","8) Франшиза — это: а) часть ущерба, которую платит клиент; б) премия банка; в) скидка.","9) Правило 50/30/20: 20% — на а) развлечения; б) сбережения; в) еду.","10) Банк по телефону просит код из SMS. Это: а) нормально; б) мошенничество; в) акция банка.","11) Признак финансовой пирамиды: а) лицензия регулятора; б) гарантированный сверхдоход и бонус за друзей; в) низкий процент.","12) Прибыль = а) выручка − расходы; б) выручка + расходы; в) только выручка."],"hand":null,"answers":[]},{"n":"2","title":"Практическое задание «Финансовый план Дианы» (8 баллов)","lines":["Данные: Диана, 15 лет, условный доход 30 000 в месяц.","Расходы: проезд 6 000, связь 3 000, перекусы 5 000, кино и кафе 8 000. Цель — графический планшет за 72 000 через 6 месяцев, накоплено 12 000.","Задание: 1) Посчитайте расходы и остаток (2 балла). 2) Посчитайте ежемесячный взнос на цель и хватит ли остатка (2 балла). 3) Диана положила 50 000 на вклад под 10% годовых с капитализацией на 2 года — сколько будет? (2 балла). 4) Диане пишут: «Вложи 10 000 и получи 40 000 через неделю, приведи друзей». Назовите 2 признака обмана (2 балла)."],"hand":null,"answers":[]},{"n":"3","title":"Чек-лист самопроверки","lines":["Ответил на все 12 вопросов.","В плане сбережений вычел уже накопленное.","В сложном проценте умножал дважды.","Назвал 2 признака мошенничества.","Проверил арифметику."],"hand":null,"answers":[]},{"n":"4","title":"Ключ (для тренера)","lines":["Тест: 1б, 2а, 3б, 4б, 5б, 6б, 7а, 8а, 9б, 10б, 11б, 12а. Практика: расходы 22 000, остаток 8 000; взнос (72 000 − 12 000) ÷ 6 = 10 000 — остатка не хватает на 2 000, нужно сократить кино и кафе или продлить срок; вклад 50 000 × 1,1 × 1,1 = 60 500; признаки: сверхдоход за короткий срок, бонус за привлечение друзей, спешка."],"hand":null,"answers":[]}],"homework":"Записать 2 темы модуля, в которых уверен, и 1 тему для повторения; подготовить вопрос к уроку работы над ошибками.","support":"Схема-опора на доске; шаблоны таблиц в практическом задании; дополнительные 3 минуты за счёт самопроверки для учеников с трудностями.","advanced":"Бонусное задание: сравнить вклад 300 000 на 2 года под 12% простых и 11% с ежегодной капитализацией и выбрать лучший (до 2 бонусных баллов, итог не выше 10).","photo":{"src":"lessons/img/08_30.jpg","author":"Vitaly Gariev","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие задания нашей итоговой работы, по-вашему, могли бы быть в PISA?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g08-l30.pptx","name":"30. Итоговая работа за полугодие (Тестирование по пройденному модулю) (8 кл).pptx","mb":1.4}},{"id":"08_31","g":8,"l":31,"topic":"Работа над ошибками и обратная связь по итоговой работе","module":"Бюджетирование (личные финансы)","format":"Итоговая работа","skills":["Финансовое мышление","Критическое мышление"],"goal":"К концу урока ученик сможет найти в своей итоговой работе по модулю «Бюджетирование» все ошибки, определить их тип, исправить с объяснением и составить личный план из 2 шагов по слабой теме.","criteria":["Я нахожу все свои ошибки и определяю их тип: термин, невнимательность, расчёт.","Я исправляю каждую ошибку и объясняю правильный ответ своими словами.","Я составляю план из 2 шагов по теме, где ошибок больше всего."],"result":"Лист работы над ошибками: таблица «ошибка — тип — правильный ответ — почему», решение 3 контрольных задач и личный план улучшения с обратной связью тренера.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Ошибка (mistake)","real":"Неверный ответ или действие, которое показывает, что нужно повторить","shown":"Неверный ответ или действие, которое показывает, что нужно повторить","truth":true,"first":"О"},{"term":"Обратная связь (feedback)","real":"Комментарий тренера или одноклассника: что получилось и что улучшить","shown":"Проверка своей работы по чек-листу до сдачи","truth":false,"first":"О"},{"term":"Тип ошибки","real":"Причина: Т — не знал термин или правило; В — невнимательность; Р — ошибка в расчёте","shown":"Причина: Т — не знал термин или правило; В — невнимательность; Р — ошибка в расчёте","truth":true,"first":"Т"},{"term":"Работа над ошибками","real":"Исправление с объяснением, почему так правильно","shown":"Комментарий тренера или одноклассника: что получилось и что улучшить","truth":false,"first":"Р"},{"term":"Личный план улучшения","real":"Конкретные шаги со сроком, чтобы закрыть пробел","shown":"Конкретные шаги со сроком, чтобы закрыть пробел","truth":true,"first":"Л"},{"term":"Самопроверка","real":"Проверка своей работы по чек-листу до сдачи","shown":"Исправление с объяснением, почему так правильно","truth":false,"first":"С"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ошибка (mistake)","def":"Неверный ответ или действие, которое показывает, что нужно повторить"},{"term":"Обратная связь (feedback)","def":"Комментарий тренера или одноклассника: что получилось и что улучшить"},{"term":"Тип ошибки","def":"Причина: Т — не знал термин или правило; В — невнимательность; Р — ошибка в расчёте"},{"term":"Работа над ошибками","def":"Исправление с объяснением, почему так правильно"},{"term":"Личный план улучшения","def":"Конкретные шаги со сроком, чтобы закрыть пробел"},{"term":"Самопроверка","def":"Проверка своей работы по чек-листу до сдачи"}],"english":"mistake — ошибка; feedback — обратная связь","concepts":{"head":"Понятия","items":["Ошибка (mistake) — это данные о пробеле, а обратная связь (feedback) — подсказка, где его искать.","Типы ошибок: Т (термин или правило), В (невнимательность), Р (расчёт)."]},"steps":{"head":"Как работать, по шагам","items":["Прочитать комментарий тренера, начиная с сильных сторон","Выписать все ошибки в таблицу","Поставить тип Т, В или Р","Найти правильный ответ в конспекте или у «эксперта»","Записать объяснение «почему»","Посчитать, какого типа ошибок больше; ж) составить 2 шага улучшения со сроком"]},"scheme":"Таблица «Ошибка — Тип — Правильно — Почему»; под ней «Мой план: шаг 1 … до …, шаг 2 … до …» и подсказки: Т → карточки «термин — определение»; В → чек-лист; Р → 3 похожие задачи.","examples":[{"lab":"Казахстанский","text":"Ученица из Астаны в задаче на план сбережений посчитала взнос как 72 000 ÷ 6 = 12 000, забыв вычесть накопленные 12 000. Тип Т/Р: правило «вычесть уже накопленное». Правильно: (72 000 − 12 000) ÷ 6 = 10 000 условных тенге. Ещё"},{"lab":"Пример","text":"При сложном проценте 50 000 под 10% на 2 года ответили 60 000 (простой процент). Правильно: 50 000 × 1,1 × 1,1 = 60 500."},{"lab":"Мировой","text":"Профессиональные инвесторы ведут «журнал ошибок», куда записывают неудачные решения и выводы из них."}],"mistake":{"myth":"Переписывание ответа без понимания","fix":"Колонка «Почему» обязательна, иначе исправление не засчитывается."},"check":[{"q":"Как не забыть вычесть накопленное?","a":"Записывать формулу полностью перед подстановкой"},{"q":"Чем простой процент отличается от сложного?","a":"В сложном проценты начисляются на проценты"},{"q":"Почему ошибки типа В исправляются чек-листом?","a":"Знание есть, нужна проверка"}],"kz":{"text":"Kaspi.kz. Компания Kaspi.kz постоянно улучшает своё приложение на основе обратной связи миллионов пользователей: исправляет неудобства и ошибки в сервисах.","link":"обратная связь и работа над ошибками — путь к лучшему продукту и в бизнесе, и в учёбе."},"world":{"text":"В мировой авиации и медицине работает культура открытого разбора ошибок: о них сообщают, чтобы не повторить, а не чтобы наказать. Эту же практику переняли многие финансовые компании.","link":""},"fact":"Рэй Далио, основатель одного из крупнейших в мире инвестиционных фондов Bridgewater Associates, в книге «Принципы» (2017) описывает, как ошибка в прогнозе в 1982 году почти разорила его фирму, и называет анализ ошибок основой своего успеха.","cards":[{"n":"1","title":"Лист работы над ошибками","lines":["Задание: заполните таблицу «№ — Моя ошибка — Тип (Т/В/Р) — Правильно — Почему». Посчитайте, какого типа ошибок больше, и допишите: «Шаг 1: … до … Шаг 2: … до …»."],"hand":"Сдать: лист тренеру.","answers":[]},{"n":"2","title":"Контрольные задачи","lines":["1) Цель 60 000 условных тенге через 5 месяцев, накоплено 15 000. Взнос?","2) Вклад 80 000 под 10% годовых с капитализацией на 2 года. Итог?","3) Ущерб 45 000, франшиза 5 000. Выплата?"],"hand":"Сдать: решения с формулами.","answers":[["","9 000."],["","96 800."],["","40 000."]]},{"n":"3","title":"Олимпиадная задача ФГиБ","lines":["Доход 50 000 условных тенге. По правилу 50/30/20 сколько откладывать и за сколько месяцев накопится 70 000?"],"hand":"Сдать: решение.","answers":[["","10 000 в месяц, 7 месяцев."]]}],"homework":"Выполнить первый шаг личного плана улучшения (карточки терминов, 3 задачи или чек-лист) и показать тренеру.","support":"Подсказки с указанием темы конспекта к каждому вопросу; работа в паре с «экспертом»; устное исправление с тренером.","advanced":"Для ученика без ошибок: составить 3 новые олимпиадные задачи ФГиБ по трудным темам модуля с решениями и стать «экспертом».","photo":{"src":"lessons/img/08_31.jpg","author":"lilartsy","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему скрытая ошибка в финансах обходится дороже, чем ошибка, разобранная открыто?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g08-l31.pptx","name":"31. Работа над ошибками и обратная связь по итоговой работе (8 кл).pptx","mb":1.4}},{"id":"08_32","g":8,"l":32,"topic":"Игра-повторение по темам полугодия","module":"Бюджетирование (личные финансы)","format":"Деловая игра","skills":["Финансовое мышление","Лидерство","Командная работа"],"goal":"К концу урока ученик сможет в командной игре правильно применить не менее 6 понятий модуля (бюджет, подушка, депозит, сложный процент, страхование, признаки мошенничества) и исправить хотя бы одну тему, где ошибался в итоговой работе.","criteria":["Я правильно применяю понятия модуля в игровых решениях и расчётах.","Я вместе с командой принимаю решение за отведённое время и выполняю свою роль.","Я называю тему, в которой раньше ошибался, и показываю, что теперь её понимаю."],"result":"Результат игры «Финансовый год семьи»: таблица капитала команды за 2 раунда и вывод команды о том, какие решения и понятия помогли.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Инструктаж","min":4},{"stage":"Раунд 1","min":10},{"stage":"Раунд 2","min":10},{"stage":"Разбор","min":8},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Повторение (review)","real":"Закрепление изученного в новых задачах","shown":"Закрепление изученного в новых задачах","truth":true,"first":"П"},{"term":"Игра (game)","real":"Задания с правилами, ролями и подсчётом результата","shown":"Договор, по которому компания компенсирует ущерб при страховом случае","truth":false,"first":"И"},{"term":"Капитал","real":"Все сбережения и вложения команды в игре","shown":"Все сбережения и вложения команды в игре","truth":true,"first":"К"},{"term":"Подушка безопасности","real":"Запас на 3–6 месяцев обязательных расходов","shown":"Задания с правилами, ролями и подсчётом результата","truth":false,"first":"П"},{"term":"Сложный процент","real":"Проценты начисляются и на ранее начисленные проценты","shown":"Проценты начисляются и на ранее начисленные проценты","truth":true,"first":"С"},{"term":"Страховой полис","real":"Договор, по которому компания компенсирует ущерб при страховом случае","shown":"Запас на 3–6 месяцев обязательных расходов","truth":false,"first":"С"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Повторение (review)","def":"Закрепление изученного в новых задачах"},{"term":"Игра (game)","def":"Задания с правилами, ролями и подсчётом результата"},{"term":"Капитал","def":"Все сбережения и вложения команды в игре"},{"term":"Подушка безопасности","def":"Запас на 3–6 месяцев обязательных расходов"},{"term":"Сложный процент","def":"Проценты начисляются и на ранее начисленные проценты"},{"term":"Страховой полис","def":"Договор, по которому компания компенсирует ущерб при страховом случае"},{"term":"Финансовая пирамида","def":"Схема, где доход платят из денег новых участников"}],"english":"review — повторение; game — игра","concepts":{"head":"Понятия для повторения","items":["бюджет и баланс, правило 50/30/20, дебетовая и кредитная карта, план сбережений, депозит, акции и облигации, простой и сложный процент, подушка безопасности, страхование и франшиза, мошенничество и пирамида, прибыль и резерв."]},"scheme":"Табло «Семья — Подушка — Депозит — Акции — Страховка — Капитал после Р1 — Событие — Капитал после Р2» и шкала баллов: верный расчёт +2, верное решение по событию +2, ошибка в расчёте −1.","examples":[{"lab":"Казахстанский","text":"Семья «Алматы» за 6 месяцев отложила 600 000: 300 000 в подушку, 200 000 на депозит, 100 000 в акции. Депозит за полгода: 200 000 × 12% ÷ 2 = 12 000. Жребий по акциям: −15% → 85 000."},{"lab":"Мировой","text":"Так же диверсифицируют вложения пенсионные фонды по всему миру."}],"mistake":{"myth":"Команды вкладывают всё в акции ради выигрыша","fix":"Событие «поломка» без подушки заставляет брать кредит под высокий процент и снижает капитал."},"check":[{"q":"Кто пострадал от поломки меньше и почему?","a":"Те, у кого была подушка или страховка"},{"q":"Почему «клуб инвесторов» — ловушка?","a":"Гарантированный сверхдоход, бонус за друзей"},{"q":"Почему не всё в акции?","a":"Риск потерь"}],"kz":{"text":"Национальный фонд Республики Казахстан. Страна откладывает часть доходов от продажи нефти в Национальный фонд — своего рода «подушку безопасности» государства, которую инвестируют и используют в трудные периоды. Используйте в разборе: сравните поведение команды-семьи и государства.","link":"правило «сначала резерв» работает и для семьи, и для страны."},"world":{"text":"Во время мировых кризисов (2008 год, пандемия 2020 года) лучше справлялись семьи и страны, у которых были резервы и разнообразные вложения.","link":""},"fact":"Национальный фонд Республики Казахстан был создан в 2000 году для накопления части доходов от нефтяного сектора и снижения зависимости экономики от колебаний цен на нефть.","cards":[{"n":"1","title":"Раунд 1 «Полгода»","lines":["Данные: свободно 100 000 в месяц, за полгода 600 000 условных тенге. Варианты: подушка (без дохода, доступна сразу); депозит 12% годовых (за полгода 6%); акции (жребий: +20% или −15%); страховка имущества 5 000 в месяц (30 000 за полгода).","Задание: распределите 600 000, посчитайте капитал после полугода по обоим исходам жребия."],"hand":"Сдать: таблицу хода.","answers":[]},{"n":"2","title":"Раунд 2: события рынка","lines":["1) Сломалась машина: ремонт 250 000. Без подушки — кредит под 2% в месяц на 6 месяцев (переплата 30 000). 2) «Клуб инвесторов» предлагает 30% в месяц и бонус за друзей. 3) Затопили соседи: ущерб 200 000; со страховкой выплата 180 000 (франшиза 20 000). 4) Банк продлевает депозит ещё на полгода под те же 12% годовых.","Задание: решите, как действовать, и пересчитайте капитал."],"hand":"Сдать: таблицу с решениями.","answers":[]},{"n":"3","title":"Олимпиадная задача ФГиБ","lines":["Семья вложила 200 000 на депозит под 12% годовых с ежемесячной выплатой процентов. Сколько она получит процентов за 6 месяцев и сколько за год?"],"hand":"Сдать: решение.","answers":[["","В месяц 200 000 × 12% ÷ 12 = 2 000; за 6 месяцев 12 000; за год 24 000."]]}],"practice":[{"type":"case","title":"Угадай термин: подушка","minutes":6,"source":"Понятие «финансовая подушка безопасности»","hook":"Запас денег на 3–6 месяцев жизни на случай беды. Как он называется?","story":["Человек потерял работу или заболел.","Если у него есть запас денег на несколько месяцев, он спокойно ищет новую работу.","Этот запас держат отдельно и не тратят на покупки."],"question":"Как называется такой запас?","options":["Финансовая подушка безопасности","Кредит","Страховой случай","Инвестиция в акции"],"answerIndex":0,"reveal":"Подушка безопасности — запас на 3–6 месяцев обязательных расходов. Её создают раньше, чем начинают инвестировать.","teams":"Команды: посчитайте подушку для семьи с расходами 400 000 тенге в месяц.","takeaway":"Подушка — первая финансовая цель."},{"type":"case","title":"Угадай термин: сложный процент","minutes":6,"source":"Понятие «сложный процент»","hook":"Проценты начисляются и на сумму вклада, и на уже начисленные проценты.","story":["Положили 100 000 под 10% в год.","Через год — 110 000. Во второй год 10% начисляют уже на 110 000.","Через 2 года — 121 000."],"question":"Как называется этот эффект?","options":["Инфляция","Простой процент","Сложный процент (капитализация)","Налог"],"answerIndex":2,"reveal":"Это сложный процент. Эйнштейну часто приписывают фразу о нём как о «восьмом чуде света», хотя доказательств, что он её говорил, нет.","teams":"Команды: посчитайте, сколько будет через 3 года под 10% с капитализацией.","takeaway":"Сложный процент растёт как снежный ком."}],"homework":"Написать 3 финансовых правила, которые вынесли из игры, и пример ситуации для каждого.","support":"Шпаргалка с формулами (процент за полгода, рост/падение в %) и готовая таблица хода на столе каждой команды.","advanced":"Роль «аудитора»: проверить расчёты другой семьи и найти ошибку за бонус; посчитать, какой была бы стратегия с наибольшим капиталом при обоих исходах жребия.","photo":{"src":"lessons/img/08_32.jpg","author":"National Cancer Institute","q":["Что вы видите на фото? Как это связано с нашей темой?","Какое решение из игры вы бы назвали главным правилом финансовой устойчивости для любой страны?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g08-l32.pptx","name":"32. Игра-повторение по темам полугодия (8 кл).pptx","mb":1.4}}];
